impl WeakHostHandle {
    pub(crate) fn downgrade(host: &HostHandle) -> Self {
        Self {
            config: host.config.clone(),
            project_catalog: Arc::downgrade(&host.project_catalog),
            restart: Arc::downgrade(&host.restart),
            state: Arc::downgrade(&host.state),
            workflow_save_lock: Arc::downgrade(&host.workflow_save_lock),
            backend_setup_refresh_lock: Arc::downgrade(&host.backend_setup_refresh_lock),
            session_schema_refresh_lock: Arc::downgrade(&host.session_schema_refresh_lock),
            settings_apply_tx: host.settings_apply_tx.clone(),
            #[cfg(feature = "test-support")]
            task_usage_refresh_sync: host.task_usage_refresh_sync.clone(),
            spawn_operations: host.spawn_operations.clone(),
        }
    }

    pub(crate) fn upgrade(&self) -> Option<HostHandle> {
        Some(HostHandle {
            project_catalog: self.project_catalog.upgrade()?,
            config: self.config.clone(),
            restart: self.restart.upgrade()?,
            state: self.state.upgrade()?,
            workflow_save_lock: self.workflow_save_lock.upgrade()?,
            backend_setup_refresh_lock: self.backend_setup_refresh_lock.upgrade()?,
            session_schema_refresh_lock: self.session_schema_refresh_lock.upgrade()?,
            settings_apply_tx: self.settings_apply_tx.clone(),
            #[cfg(feature = "test-support")]
            task_usage_refresh_sync: self.task_usage_refresh_sync.clone(),
            spawn_operations: self.spawn_operations.clone(),
            spawn_operation_owner: None,
        })
    }
}

impl Clone for HostHandle {
    fn clone(&self) -> Self {
        Self {
            project_catalog: self.project_catalog.clone(),
            config: self.config.clone(),
            restart: Arc::clone(&self.restart),
            state: Arc::clone(&self.state),
            workflow_save_lock: Arc::clone(&self.workflow_save_lock),
            backend_setup_refresh_lock: Arc::clone(&self.backend_setup_refresh_lock),
            session_schema_refresh_lock: Arc::clone(&self.session_schema_refresh_lock),
            settings_apply_tx: self.settings_apply_tx.clone(),
            #[cfg(feature = "test-support")]
            task_usage_refresh_sync: self.task_usage_refresh_sync.clone(),
            spawn_operations: self.spawn_operations.clone(),
            spawn_operation_owner: None,
        }
    }
}

impl Drop for HostHandle {
    fn drop(&mut self) {
        if let Some(owner) = self.spawn_operation_owner.as_ref() {
            self.project_catalog.stop();
            self.config.stop();
            owner.begin_shutdown();
        }
    }
}

struct PendingAgentSessionPublication {
    agent_id: AgentId,
    publish_tx: Option<mpsc::UnboundedSender<()>>,
}

#[derive(Default)]
struct AgentVisibilityRegistry {
    entries: HashMap<AgentId, AgentVisibilityEntry>,
}

struct AgentVisibilityEntry {
    phase: AgentVisibilityPhase,
    fanout_active: bool,
    host_streams: HashSet<StreamPath>,
    fanout_covered: HashSet<StreamPath>,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum AgentVisibilityPhase {
    Pending,
    Fanout,
    Visible,
    Cancelled,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum StartupFailureVisibility {
    CleanupUnpublished,
    AwaitPublication,
}

impl Default for AgentVisibilityEntry {
    fn default() -> Self {
        Self {
            phase: AgentVisibilityPhase::Visible,
            fanout_active: false,
            host_streams: HashSet::new(),
            fanout_covered: HashSet::new(),
        }
    }
}

impl AgentVisibilityRegistry {
    fn begin_pending(&mut self, agent_id: AgentId) {
        self.entries.insert(
            agent_id,
            AgentVisibilityEntry {
                phase: AgentVisibilityPhase::Pending,
                fanout_active: false,
                host_streams: HashSet::new(),
                fanout_covered: HashSet::new(),
            },
        );
    }

    fn begin_fanout(&mut self, agent_id: &AgentId) -> bool {
        let visibility = &mut self.entries;
        let Some(entry) = visibility.get_mut(agent_id) else {
            return false;
        };
        if entry.phase != AgentVisibilityPhase::Pending {
            return false;
        }
        entry.phase = AgentVisibilityPhase::Fanout;
        entry.fanout_active = true;
        true
    }

    fn begin_fanout_batch(&mut self, agent_id: &AgentId, covered: HashSet<StreamPath>) {
        let visibility = &mut self.entries;
        let Some(entry) = visibility.get_mut(agent_id) else {
            return;
        };
        if entry.phase == AgentVisibilityPhase::Fanout && entry.fanout_active {
            entry.fanout_covered = covered;
        }
    }

    fn claim_startup_failure(&mut self, agent_id: &AgentId) -> StartupFailureVisibility {
        let visibility = &mut self.entries;
        let Some(entry) = visibility.get_mut(agent_id) else {
            return StartupFailureVisibility::CleanupUnpublished;
        };
        match entry.phase {
            AgentVisibilityPhase::Pending => {
                entry.phase = AgentVisibilityPhase::Cancelled;
                entry.fanout_active = false;
                StartupFailureVisibility::CleanupUnpublished
            }
            AgentVisibilityPhase::Fanout | AgentVisibilityPhase::Visible => {
                StartupFailureVisibility::AwaitPublication
            }
            AgentVisibilityPhase::Cancelled => StartupFailureVisibility::CleanupUnpublished,
        }
    }

    fn may_emit_new_agent(&self, agent_id: &AgentId) -> bool {
        self.entries
            .get(agent_id)
            .is_some_and(|entry| entry.phase == AgentVisibilityPhase::Fanout && entry.fanout_active)
    }

    fn finish_fanout(&mut self, agent_id: &AgentId) -> bool {
        let visibility = &mut self.entries;
        let Some(entry) = visibility.get_mut(agent_id) else {
            return true;
        };
        entry.fanout_active = false;
        entry.fanout_covered.clear();
        if entry.phase == AgentVisibilityPhase::Fanout {
            entry.phase = AgentVisibilityPhase::Visible;
            false
        } else {
            true
        }
    }

    fn cancel_outer_spawn(&mut self, agent_id: &AgentId) {
        if let Some(entry) = self.entries.get_mut(agent_id) {
            entry.phase = AgentVisibilityPhase::Cancelled;
            entry.fanout_active = false;
        }
    }

    fn request_cleanup(&mut self, agent_id: &AgentId) -> bool {
        let visibility = &mut self.entries;
        let Some(entry) = visibility.get_mut(agent_id) else {
            return false;
        };
        entry.phase = AgentVisibilityPhase::Cancelled;
        entry.fanout_active
    }

    fn cleanup_is_requested(&self, agent_id: &AgentId) -> bool {
        self.entries
            .get(agent_id)
            .is_some_and(|entry| entry.phase == AgentVisibilityPhase::Cancelled)
    }

    fn claim_bootstrap_delivery(
        &mut self,
        agent_id: &AgentId,
        host_stream: &StreamPath,
        publicly_bound: bool,
    ) -> bool {
        let visibility = &mut self.entries;
        let Some(entry) = visibility.get_mut(agent_id) else {
            return publicly_bound;
        };
        let eligible = match entry.phase {
            AgentVisibilityPhase::Pending | AgentVisibilityPhase::Cancelled => false,
            AgentVisibilityPhase::Fanout => !entry.fanout_covered.contains(host_stream),
            AgentVisibilityPhase::Visible => true,
        };
        if eligible {
            entry.host_streams.insert(host_stream.clone());
        }
        eligible
    }

    fn record_new_agent(&mut self, agent_id: AgentId, host_stream: StreamPath) {
        self.entries
            .entry(agent_id)
            .or_default()
            .host_streams
            .insert(host_stream);
    }

    fn visible_host_streams(&self, agent_id: &AgentId) -> HashSet<StreamPath> {
        self.entries
            .get(agent_id)
            .map(|entry| entry.host_streams.clone())
            .unwrap_or_default()
    }

    fn publication_cancelled(&self, agent_id: &AgentId) -> bool {
        self.entries
            .get(agent_id)
            .is_some_and(|entry| entry.phase == AgentVisibilityPhase::Cancelled)
    }

    fn publication_pending(&self, agent_id: &AgentId) -> bool {
        self.entries.get(agent_id).is_some_and(|entry| {
            matches!(
                entry.phase,
                AgentVisibilityPhase::Pending | AgentVisibilityPhase::Fanout
            )
        })
    }

    fn remove_agent(&mut self, agent_id: &AgentId) {
        self.entries.remove(agent_id);
    }

    fn remove_host_stream(&mut self, host_stream: &StreamPath) {
        let visibility = &mut self.entries;
        for entry in visibility.values_mut() {
            entry.host_streams.remove(host_stream);
            entry.fanout_covered.remove(host_stream);
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum AgentCloseIntent {
    User,
    UnclaimedCreation,
}

struct UnpublishedAgentGuard {
    host: HostHandle,
    runtime: tokio::runtime::Handle,
    agent_id: Option<AgentId>,
    #[cfg(feature = "test-support")]
    cleanup_complete: Option<oneshot::Sender<Result<(), protocol::CommandErrorPayload>>>,
}

impl UnpublishedAgentGuard {
    fn new(
        host: HostHandle,
        agent_id: AgentId,
        #[cfg(feature = "test-support")] cleanup_complete: Option<
            oneshot::Sender<Result<(), protocol::CommandErrorPayload>>,
        >,
    ) -> Self {
        Self {
            host,
            runtime: tokio::runtime::Handle::current(),
            agent_id: Some(agent_id),
            #[cfg(feature = "test-support")]
            cleanup_complete,
        }
    }

    fn disarm(&mut self) {
        self.agent_id = None;
    }
}

impl Drop for UnpublishedAgentGuard {
    fn drop(&mut self) {
        let Some(agent_id) = self.agent_id.take() else {
            return;
        };
        let host = self.host.clone();
        #[cfg(feature = "test-support")]
        let cleanup_complete = self.cleanup_complete.take();
        self.runtime.spawn(async move {
            #[cfg(feature = "test-support")]
            let stream = new_instance_stream(&agent_id);
            let outcome = host.cleanup_unclaimed_agent(agent_id).await;
            #[cfg(feature = "test-support")]
            if let Some(complete) = cleanup_complete {
                let _ = complete
                    .send(outcome.map_err(|error| error.to_payload(stream, FrameKind::SpawnAgent)));
            }
            #[cfg(not(feature = "test-support"))]
            drop(outcome);
        });
    }
}

#[derive(Clone)]
struct SpawnVisibility {
    changed: Arc<tokio::sync::Notify>,
    agent_id: AgentId,
    state: Arc<StateOwner<HostState>>,
}

struct SpawnVisibilityGuard {
    visibility: SpawnVisibility,
    armed: bool,
}

impl SpawnVisibility {
    fn new(agent_id: AgentId, state: &mut HostState, owner: Arc<StateOwner<HostState>>) -> Self {
        state.agent_visibility.begin_pending(agent_id.clone());
        Self {
            changed: Arc::new(tokio::sync::Notify::new()),
            agent_id,
            state: owner,
        }
    }

    async fn begin_fanout(&self) -> bool {
        let agent_id = self.agent_id.clone();
        self.state
            .with(move |state| state.agent_visibility.begin_fanout(&agent_id))
            .await
    }

    fn finish_new_agent_fanout(&self, state: &mut HostState) -> bool {
        let cleanup_requested = state.agent_visibility.finish_fanout(&self.agent_id);
        self.changed.notify_one();
        cleanup_requested
    }

    fn cancel_outer_spawn(&self) {
        let agent_id = self.agent_id.clone();
        let changed = Arc::clone(&self.changed);
        if let Err(error) = self.state.apply(move |state| {
            state.agent_visibility.cancel_outer_spawn(&agent_id);
            changed.notify_one();
        }) {
            tracing::error!(%error, "cannot cancel agent publication after state owner stopped");
        }
    }

    async fn cleanup_is_requested(&self) -> bool {
        let agent_id = self.agent_id.clone();
        self.state
            .with(move |state| state.agent_visibility.cleanup_is_requested(&agent_id))
            .await
    }

    async fn request_cleanup(&self) {
        loop {
            let changed = self.changed.notified();
            let agent_id = self.agent_id.clone();
            let wait_for_fanout = self
                .state
                .with(move |state| state.agent_visibility.request_cleanup(&agent_id))
                .await;
            if !wait_for_fanout {
                return;
            }
            changed.await;
        }
    }

    async fn claim_startup_failure(&self) -> StartupFailureVisibility {
        let agent_id = self.agent_id.clone();
        let changed = Arc::clone(&self.changed);
        self.state
            .with(move |state| {
                let outcome = state.agent_visibility.claim_startup_failure(&agent_id);
                if outcome == StartupFailureVisibility::CleanupUnpublished {
                    changed.notify_one();
                }
                outcome
            })
            .await
    }
}

impl SpawnVisibilityGuard {
    fn new(visibility: SpawnVisibility) -> Self {
        Self {
            visibility,
            armed: true,
        }
    }

    fn disarm(&mut self) {
        self.armed = false;
    }
}

impl Drop for SpawnVisibilityGuard {
    fn drop(&mut self) {
        if self.armed {
            self.visibility.cancel_outer_spawn();
        }
    }
}

type InflightResumeClaim = tokio_util::sync::DropGuard;

fn live_session_owner(state: &HostState, session_id: &SessionId) -> Option<AgentId> {
    let owns_session = |agent_id: &AgentId, id: &SessionId| {
        id == session_id
            && state
                .registry
                .agent_handle(agent_id)
                .is_some_and(|handle| !handle.is_closing())
    };
    state
        .agent_sessions
        .iter()
        .chain(state.pending_agent_sessions.iter())
        .find_map(|(agent_id, id)| owns_session(agent_id, id).then(|| agent_id.clone()))
        .or_else(|| {
            state.registry.agent_ids().into_iter().find(|agent_id| {
                state
                    .registry
                    .agent_handle(agent_id)
                    .filter(|handle| !handle.is_closing())
                    .and_then(|handle| handle.snapshot().session_id)
                    .is_some_and(|id| &id == session_id)
            })
        })
}

impl PendingAgentSessionPublication {
    fn publish(mut self) {
        let Some(publish_tx) = self.publish_tx.take() else {
            tracing::error!(
                agent_id = %self.agent_id,
                "agent session publication guard was consumed before publication"
            );
            return;
        };
        if publish_tx.send(()).is_err() {
            tracing::debug!(
                agent_id = %self.agent_id,
                "agent session registration ended before publication gate"
            );
        }
    }
}

fn authorize_agent_session_publication(
    session_registration_publish: PendingAgentSessionPublication,
    session_summary_count_tx: &HostSessionSummaryCountTx,
    agent_id: &AgentId,
) {
    session_registration_publish.publish();
    let _ = session_summary_count_tx.send(HostSessionSummaryCountEvent::AgentPublished(
        agent_id.clone(),
    ));
}

impl Drop for PendingAgentSessionPublication {
    fn drop(&mut self) {
        self.publish_tx.take();
    }
}

