    /// Settles pending status or elapsed refresh work, then acknowledges the
    /// armed deadline. A future timer is not fired or rearmed by this barrier.
    #[cfg(feature = "test-support")]
    pub async fn synchronize_task_usage_refresh_for_test(&self) {
        let (reply, done) = oneshot::channel();
        self.task_usage_refresh_sync
            .send(reply)
            .expect("task usage worker is running");
        done.await.expect("task usage worker synchronized");
    }

    /// Returns when a task's in-progress working or waiting time is next
    /// worth re-sending, if any task has such a phase.
    pub(crate) async fn fan_out_task_token_usages(&self) -> Option<Duration> {
        let (handles, closed_snapshots, live_agent_ids, agent_sessions) = self
            .state
            .with(|state| task_token_usage_sources_for_state(state))
            .await;
        let mut payloads = task_token_usage_rollups_from_handles(
            handles,
            closed_snapshots,
            &live_agent_ids,
            &agent_sessions,
            #[cfg(feature = "test-support")]
            None,
        )
        .await;
        attach_learning_accounting(&mut payloads, self.config.usage().await);
        self.state
            .with(move |state| fan_out_task_token_usages(state, payloads))
            .await
    }

    pub(crate) async fn backend_native_settings_write(
        &self,
        payload: protocol::BackendNativeSettingsWritePayload,
        output: &Stream,
    ) -> AppResult<()> {
        self.queue_settings_apply(SettingsMutation::Native(Box::new(payload), output.clone()))
            .await
    }

    async fn backend_native_settings_write_now(
        &self,
        payload: protocol::BackendNativeSettingsWritePayload,
        host_output_stream: &Stream,
    ) -> AppResult<()> {
        const OPERATION: &str = "backend_native_settings_write";
        let outcome = crate::backend::write_native_settings(
            payload.backend,
            payload.settings,
            &crate::backend::BackendProbeContext::default(),
        )
        .await;
        if outcome.refresh_required {
            self.refresh_backend_config_snapshots_after_native_save()
                .await;
            self.refresh_session_schemas_with_fanout(true).await;
        }
        let outcome = outcome.result;

        let current_etag = {
            {
                self.state
                    .with(move |state| {
                        let store = Arc::clone(&state.settings_store);
                        let settings = store
                            .get()
                            .map_err(|error| AppError::internal(OPERATION, anyhow!(error)))?;

                        Ok::<_, AppError>(settings_wire_projection(&store, &settings).2)
                    })
                    .await?
            }
        };
        let (applied, field_errors) = match outcome {
            Ok(()) => (true, Vec::new()),
            Err(message) => (
                false,
                vec![protocol::SettingsFieldError {
                    pointer: "".to_owned(),
                    code: protocol::SettingsErrorCode::BackendRejected,
                    message,
                }],
            ),
        };
        let result = protocol::SettingsWriteResultPayload {
            write_id: payload.write_id,
            applied,
            current_etag,
            field_errors,
        };
        let value = serde_json::to_value(result).map_err(|error| {
            AppError::internal_message(
                OPERATION,
                "failed to serialize SettingsWriteResult payload",
                error,
            )
        })?;
        let _ = host_output_stream.send_value(FrameKind::SettingsWriteResult, value);
        Ok(())
    }

    pub(crate) async fn invoke_settings_action(
        &self,
        payload: protocol::InvokeSettingsActionPayload,
        output: &Stream,
    ) -> AppResult<()> {
        self.queue_settings_apply(SettingsMutation::Action(Box::new(payload), output.clone()))
            .await
    }

    async fn invoke_settings_action_now(
        &self,
        payload: protocol::InvokeSettingsActionPayload,
        host_output_stream: &Stream,
    ) -> AppResult<()> {
        const OPERATION: &str = "invoke_settings_action";
        let outcome: Result<Vec<String>, String> = Err(format!(
            "{:?} does not support settings resource actions",
            payload.backend
        ));

        if let Ok(tombstones) = &outcome {
            self.refresh_backend_config_snapshots_after_settings_action(tombstones)
                .await;
            self.refresh_session_schemas_with_fanout(true).await;
        }

        let current_etag = {
            {
                self.state
                    .with(move |state| {
                        let store = Arc::clone(&state.settings_store);
                        let settings = store
                            .get()
                            .map_err(|error| AppError::internal(OPERATION, anyhow!(error)))?;

                        Ok::<_, AppError>(settings_wire_projection(&store, &settings).2)
                    })
                    .await?
            }
        };
        let (applied, field_errors) = match outcome {
            Ok(_) => (true, Vec::new()),
            Err(message) => (
                false,
                vec![protocol::SettingsFieldError {
                    pointer: payload.resource,
                    code: protocol::SettingsErrorCode::BackendRejected,
                    message,
                }],
            ),
        };
        let result = protocol::SettingsWriteResultPayload {
            write_id: payload.write_id,
            applied,
            current_etag,
            field_errors,
        };
        let value = serde_json::to_value(result).map_err(|error| {
            AppError::internal_message(
                OPERATION,
                "failed to serialize SettingsWriteResult payload",
                error,
            )
        })?;
        let _ = host_output_stream.send_value(FrameKind::SettingsWriteResult, value);
        Ok(())
    }

    async fn finish_settings_apply(&self, effects: SettingsApplyEffects) {
        if effects.refresh_session_schemas
            || effects.refresh_backend_config_snapshots
            || !effects.refresh_schema_backends.is_empty()
        {
            if effects.refresh_session_schemas {
                self.refresh_session_schemas().await;
            }
            for kind in effects.refresh_schema_backends {
                self.refresh_session_schema_for_backend(kind).await;
            }
            if effects.refresh_backend_config_snapshots {
                self.refresh_backend_config_snapshots().await;
            }
        }
    }

    /// Apply an atomic, compare-and-swap settings write.
    async fn queue_settings_apply(&self, mutation: SettingsMutation) -> AppResult<()> {
        #[cfg(feature = "test-support")]
        let queued_gate = match &mutation {
            SettingsMutation::Write(payload, _) => {
                let payload = payload.to_owned();
                self.state
                    .with(move |state| {
                        let payload = &payload;

                        state
                            .settings_queued_test_gate
                            .as_ref()
                            .filter(|(id, _)| *id == payload.write_id.0)
                            .map(|(_, gate)| gate.clone())
                    })
                    .await
            }
            _ => None,
        };
        let (reply, response) = oneshot::channel();
        self.settings_apply_tx
            .send(SettingsApplyCommand { mutation, reply })
            .map_err(|_| {
                AppError::internal(
                    "settings_apply",
                    anyhow!("Settings lifecycle actor stopped"),
                )
            })?;
        #[cfg(feature = "test-support")]
        if let Some(gate) = queued_gate {
            let _ = gate.entered_tx.send(());
        }
        response.await.map_err(|_| {
            AppError::internal(
                "settings_apply",
                anyhow!("Settings lifecycle did not complete"),
            )
        })?
    }

    pub(crate) async fn settings_write(
        &self,
        payload: protocol::SettingsWritePayload,
        output: &Stream,
    ) -> AppResult<()> {
        self.queue_settings_apply(SettingsMutation::Write(Box::new(payload), output.clone()))
            .await
    }

    async fn settings_write_now(
        &self,
        payload: protocol::SettingsWritePayload,
        host_output_stream: &Stream,
    ) -> AppResult<()> {
        const OPERATION: &str = "settings_write";
        use protocol::{SettingExpectation, SettingsErrorCode, SettingsFieldError};

        let write_id = payload.write_id.clone();
        let result_output = host_output_stream.clone();
        let result_write_id = write_id.clone();
        let emit_result =
            move |applied: bool, current_etag: String, field_errors: Vec<SettingsFieldError>| {
                let result = protocol::SettingsWriteResultPayload {
                    write_id: result_write_id.clone(),
                    applied,
                    current_etag,
                    field_errors,
                };
                let value = serde_json::to_value(&result)
                    .expect("failed to serialize SettingsWriteResult payload");
                let _ = result_output.send_value(FrameKind::SettingsWriteResult, value);
            };

        let schema = settings_model::host_settings_schema();
        let mut field_errors: Vec<SettingsFieldError> = Vec::new();
        let push_error = |errors: &mut Vec<SettingsFieldError>,
                          pointer: &str,
                          code: SettingsErrorCode,
                          message: String| {
            errors.push(SettingsFieldError {
                pointer: pointer.to_owned(),
                code,
                message,
            });
        };

        // Keep each write's CAS, backend propagation, fanout, and result in
        // one order even while backend I/O runs outside the state owner.
        let host = self.clone();
        let emit_for_validation = emit_result.clone();
        let prepared = {
            self.state.with_async(move |state| Box::pin(async move {


            let emit_result = emit_for_validation;

        let settings_store = Arc::clone(&state.settings_store);
        let store = Arc::clone(&settings_store);
        let current = store
            .get()
            .map_err(|error| AppError::internal(OPERATION, anyhow!(error)))?;
        let raw_doc = serde_json::to_value(&current)
            .map_err(|error| AppError::internal(OPERATION, anyhow!(error)))?;
        let (visible_doc, _configured_secrets, current_etag) =
            settings_wire_projection(&store, &current);

        if payload.ops.is_empty() {
            push_error(
                &mut field_errors,
                "",
                SettingsErrorCode::Invalid,
                "a settings write must carry at least one operation".to_owned(),
            );
        }
        if payload.ops.len() > protocol::SETTINGS_WRITE_MAX_OPS {
            push_error(
                &mut field_errors,
                "",
                SettingsErrorCode::Invalid,
                format!(
                    "a settings write may carry at most {} operations",
                    protocol::SETTINGS_WRITE_MAX_OPS
                ),
            );
        }

        let mut parsed_ops: Vec<(
            Vec<String>,
            settings_model::SecretRelation,
            &protocol::SettingOp,
        )> = Vec::new();
        for op in &payload.ops {
            let Some(tokens) = protocol::parse_json_pointer(op.path()) else {
                push_error(
                    &mut field_errors,
                    op.path(),
                    SettingsErrorCode::Invalid,
                    "not a valid RFC 6901 JSON pointer".to_owned(),
                );
                continue;
            };
            if tokens.iter().any(|token| token == "-") {
                // RFC 6901's `-` names the always-absent after-last element:
                // every stale append would pass an "expected absent"
                // precondition, so it has no meaningful CAS. Write the
                // element index or the whole array instead.
                push_error(
                    &mut field_errors,
                    op.path(),
                    SettingsErrorCode::Invalid,
                    "array append ('-') is not supported: an always-absent target has no meaningful compare-and-swap precondition; write the element index or the whole array".to_owned(),
                );
                continue;
            }
            if !settings_model::schema_knows_path(schema, &tokens) {
                push_error(
                    &mut field_errors,
                    op.path(),
                    SettingsErrorCode::UnknownPath,
                    "the settings schema knows no such path".to_owned(),
                );
                continue;
            }
            let relation = settings_model::secret_relation(schema, &tokens);
            if relation.strict_ancestor_of_secret {
                push_error(
                    &mut field_errors,
                    op.path(),
                    SettingsErrorCode::SecretSubtree,
                    "replacing an ancestor of a secret value could silently clear it; write the secret path directly".to_owned(),
                );
                continue;
            }
            if relation.at_or_inside_secret
                && matches!(op.expected(), SettingExpectation::Value { .. })
            {
                push_error(
                    &mut field_errors,
                    op.path(),
                    SettingsErrorCode::SecretSubtree,
                    "secret values are never on the wire; use a version-token or absent expectation"
                        .to_owned(),
                );
                continue;
            }
            parsed_ops.push((tokens, relation, op));
        }

        let mut overlap_pointers: Vec<String> = Vec::new();
        for (index, (tokens_a, _, op_a)) in parsed_ops.iter().enumerate() {
            for (tokens_b, _, op_b) in parsed_ops.iter().skip(index + 1) {
                if settings_model::paths_overlap(tokens_a, tokens_b) {
                    for path in [op_a.path(), op_b.path()] {
                        if !overlap_pointers.iter().any(|seen| seen == path) {
                            overlap_pointers.push(path.to_owned());
                        }
                    }
                }
            }
        }
        for pointer in &overlap_pointers {
            push_error(
                &mut field_errors,
                pointer,
                SettingsErrorCode::OverlapRejected,
                "overlaps another operation in the same write".to_owned(),
            );
        }

        // Secret CAS uses a server-issued token because the true value is
        // absent from the client-visible document.
        if field_errors.is_empty() {
            for (tokens, relation, op) in &parsed_ops {
                let matches = match op.expected() {
                    // `null` matches both an explicit null and an absent
                    // member — clients cannot tell those apart in a document.
                    SettingExpectation::Value { value } => {
                        settings_model::pointer_get(&visible_doc, tokens)
                            .unwrap_or(&serde_json::Value::Null)
                            == value
                    }
                    SettingExpectation::Version { token } => {
                        if relation.at_or_inside_secret {
                            let key = store
                                .secret_token_key()
                                .map_err(|error| AppError::internal(OPERATION, anyhow!(error)))?;
                            token
                                == &settings_model::secret_version_token(
                                    &key,
                                    op.path(),
                                    settings_model::pointer_get(&raw_doc, tokens),
                                )
                        } else {
                            token
                                == &settings_model::version_token(settings_model::pointer_get(
                                    &visible_doc,
                                    tokens,
                                ))
                        }
                    }
                    SettingExpectation::Absent => {
                        let source = if relation.at_or_inside_secret {
                            &raw_doc
                        } else {
                            &visible_doc
                        };
                        matches!(
                            settings_model::pointer_get(source, tokens),
                            None | Some(serde_json::Value::Null)
                        )
                    }
                };
                if !matches {
                    push_error(
                        &mut field_errors,
                        op.path(),
                        SettingsErrorCode::Conflict,
                        "the current value is not the expected one (concurrent edit); re-read and retry".to_owned(),
                    );
                }
            }
        }

        if !field_errors.is_empty() {
            drop(store);

            emit_result(false, current_etag, field_errors);
            return Ok(None);
        }

        let mut candidate_doc = raw_doc;
        for (tokens, _, op) in &parsed_ops {
            let outcome = match op {
                protocol::SettingOp::Replace { value, .. } => {
                    settings_model::pointer_set(&mut candidate_doc, tokens, value.clone())
                }
                protocol::SettingOp::Remove { .. } => {
                    settings_model::pointer_remove(&mut candidate_doc, tokens)
                }
            };
            if let Err(message) = outcome {
                push_error(
                    &mut field_errors,
                    op.path(),
                    SettingsErrorCode::Invalid,
                    message,
                );
            }
        }
        if !field_errors.is_empty() {
            drop(store);

            emit_result(false, current_etag, field_errors);
            return Ok(None);
        }

        let mut candidate: settings_model::HostSettings =
            match serde_json::from_value(candidate_doc) {
                Ok(candidate) => candidate,
                Err(error) => {
                    drop(store);

                    push_error(
                        &mut field_errors,
                        if parsed_ops.len() == 1 {
                            parsed_ops[0].2.path()
                        } else {
                            ""
                        },
                        SettingsErrorCode::Invalid,
                        format!("the resulting document is not a valid settings document: {error}"),
                    );
                    emit_result(false, current_etag, field_errors);
                    return Ok(None);
                }
            };

        // Normalizing enabled backends may clear the default. Reject a write
        // that also edits the default rather than silently clobbering it.
        candidate.enabled_backends =
            crate::store::settings::normalize_backend_list(candidate.enabled_backends);
        if !current.complexity_tiers_enabled && candidate.complexity_tiers_enabled {
            for kind in crate::backend::SUPPORTED_BACKENDS {
                if let Some(config) = crate::backend::default_persisted_tier_config(kind) {
                    candidate.backend_tier_configs.entry(kind).or_insert(config);
                }
            }
        }

        let default_orphaned = candidate
            .default_backend
            .is_some_and(|kind| !candidate.enabled_backends.contains(&kind));
        if default_orphaned {
            let touched = |field: &str| {
                parsed_ops
                    .iter()
                    .any(|(tokens, _, _)| tokens.first().is_some_and(|token| token == field))
            };
            if touched("default_backend") && touched("enabled_backends") {
                push_error(
                    &mut field_errors,
                    "/default_backend",
                    SettingsErrorCode::OverlapRejected,
                    "the enabled_backends write implicitly normalizes default_backend, which another operation targets".to_owned(),
                );
            } else if touched("default_backend") {
                push_error(
                    &mut field_errors,
                    "/default_backend",
                    SettingsErrorCode::Invalid,
                    "default_backend must be one of enabled_backends".to_owned(),
                );
            } else {
                candidate.default_backend = None;
            }
        }

        // These live checks depend on the old/new diff, not JSON shape alone.
        let default_selection_touched = parsed_ops.iter().any(|(tokens, _, _)| {
            tokens.first().is_some_and(|token| {
                token == "default_backend" || token == "default_launch_profile_id"
            })
        });
        if default_selection_touched
            && let Some(profile_id) = candidate.default_launch_profile_id.as_ref()
        {
            let catalog = launch_profile_catalog_for_settings(state, &candidate);
            match resolve_launch_profile_from_catalog(&catalog, profile_id) {
                Ok(profile) if Some(profile.backend_kind) == candidate.default_backend => {}
                Ok(_) => push_error(
                    &mut field_errors,
                    "/default_launch_profile_id",
                    SettingsErrorCode::Invalid,
                    "the default launch profile must target default_backend".to_owned(),
                ),
                Err(message) => push_error(
                    &mut field_errors,
                    "/default_launch_profile_id",
                    SettingsErrorCode::Unavailable,
                    message,
                ),
            }
        }
        if candidate.supervisor.max_kicks_per_task != current.supervisor.max_kicks_per_task
            && candidate.supervisor.max_kicks_per_task == 0
        {
            push_error(
                &mut field_errors,
                "/supervisor/max_kicks_per_task",
                SettingsErrorCode::Invalid,
                "supervisor max kicks per task must be at least 1; disable the supervisor instead of setting it to 0".to_owned(),
            );
        }

        let backend_tiers_touched = parsed_ops.iter().any(|(tokens, _, _)| {
            tokens
                .first()
                .is_some_and(|token| token == "backend_tier_configs")
        });
        for (backend, config) in &candidate.backend_tier_configs {
            if !backend_tiers_touched {
                continue;
            }
            let prior = current.backend_tier_configs.get(backend);
            // A tier left untouched keeps whatever it held, even if the model
            // catalog has since dropped it; revalidating it would reject every
            // edit to the other tier and leave no way to repair either one.
            let changed_tiers = [
                ("Low", &config.low, prior.map(|prior| &prior.low)),
                ("High", &config.high, prior.map(|prior| &prior.high)),
            ]
            .into_iter()
            .filter(|(_, values, prior)| !values.0.is_empty() && *prior != Some(*values))
            .collect::<Vec<_>>();
            if changed_tiers.is_empty() {
                continue;
            }
            let pointer = format!("/backend_tier_configs/{}", backend_wire_slug(*backend));
            let Some(schema) = session_schema_for_backend(state, *backend, None) else {
                push_error(
                    &mut field_errors,
                    &pointer,
                    SettingsErrorCode::Unavailable,
                    format!("{backend:?} session settings schema unavailable"),
                );
                continue;
            };
            for (tier, values, _) in changed_tiers {
                if let Err(error) = validate_session_settings_values(&schema, values) {
                    push_error(
                        &mut field_errors,
                        &pointer,
                        SettingsErrorCode::Invalid,
                        format!("invalid {tier} tier: {error}"),
                    );
                }
            }
        }
        for (backend, values) in &candidate.backend_config {
            if current.backend_config.get(backend) == Some(values) || values.0.is_empty() {
                continue;
            }
            match crate::backend::validate_backend_config_values(*backend, values) {
                Ok(_) => {}
                Err(message) => push_error(
                    &mut field_errors,
                    &format!("/backend_config/{}", backend_wire_slug(*backend)),
                    SettingsErrorCode::Invalid,
                    message,
                ),
            }
        }
        if !field_errors.is_empty() {
            drop(store);

            emit_result(false, current_etag, field_errors);
            return Ok(None);
        }

        if candidate.tychat != current.tychat
            || candidate.enabled_backends != current.enabled_backends
            || candidate.launch_profiles != current.launch_profiles
        {

            let custom_agent_exists = candidate
                .tychat
                .custom_agent_id
                .as_ref()
                .is_none_or(|id| state.custom_agent_store.get(id).is_some());

            if let Err(message) =
                tychat::validate_tychat_settings(state, &candidate, custom_agent_exists)
            {
                push_error(
                    &mut field_errors,
                    "/tychat",
                    SettingsErrorCode::Invalid,
                    message,
                );
            }
            if !field_errors.is_empty() {
                drop(store);

                emit_result(false, current_etag, field_errors);
                return Ok(None);
            }
        }

        // Commit before external propagation so a downstream failure cannot
        // leave external state changed while the host store remains stale.
        let committed = match host.config.replace(current.clone(), candidate).await {
            Ok(committed) => committed,
            Err(message) => {
                drop(store);

                push_error(
                    &mut field_errors,
                    if parsed_ops.len() == 1 {
                        parsed_ops[0].2.path()
                    } else {
                        ""
                    },
                    SettingsErrorCode::Invalid,
                    message,
                );
                emit_result(false, current_etag, field_errors);
                return Ok(None);
            }
        };
        drop(store);

        let mut effects = SettingsApplyEffects::from_diff(&current, &committed);
        if parsed_ops.iter().any(|(tokens, _, _)| {
            tokens
                .first()
                .is_some_and(|token| token == "enabled_backends")
        }) {
            effects.refresh_session_schemas = true;
            effects.refresh_backend_config_snapshots = true;
        }

            fan_out_host_settings(state, committed.clone(), effects.refresh_voice_capabilities);
            apply_agent_activity_summary_setting(state, &committed);
            apply_agent_supervisor_setting(state, &committed);
            state.mobile_access.settings_changed(committed.clone());
            fan_out_launch_profile_catalog(state);
            Ok::<_, AppError>(Some((current, committed, effects, settings_store)))
        })).await
        }?;
        let Some((current, committed, effects, settings_store)) = prepared else {
            return Ok(());
        };
        self.finish_settings_apply(effects).await;
        let propagation_errors: Vec<SettingsFieldError> = Vec::new();

        if current.tychat != committed.tychat
            || current.enabled_backends != committed.enabled_backends
            || current.launch_profiles != committed.launch_profiles
        {
            let service = self.state.with(|state| state.tychat.clone()).await;
            if let Err(reason) = self.reconcile_tychat(false).await {
                service.fail(reason).await;
            }
            service.settings_changed();
        }
        if current.chatgpt_dots_enabled != committed.chatgpt_dots_enabled {
            let dots = self.state.with(|state| state.dots.clone()).await;
            if let Err(reason) = dots.configure(committed.chatgpt_dots_enabled) {
                self.publish_dots_state(protocol::DotsStatePayload {
                    status: protocol::DotsConnectionStatus::Failed { reason },
                    ..Default::default()
                })
                .await;
            }
        }
        #[cfg(feature = "test-support")]
        {
            let gate = {
                self.state
                    .with(move |state| {
                        state
                            .settings_lifecycle_test_gate
                            .as_ref()
                            .filter(|(id, _)| *id == write_id.0)
                            .map(|(_, gate)| gate.clone())
                    })
                    .await
            };
            if let Some(gate) = gate {
                wait_for_spawn_operation_test_gate_inner(&gate).await;
            }
        }
        let new_etag = {
            let store = Arc::clone(&settings_store);
            let (_doc, _configured_secrets, etag) = settings_wire_projection(&store, &committed);
            etag
        };
        emit_result(true, new_etag, propagation_errors);
        Ok(())
    }

    pub(crate) async fn settings_write_for_internal_caller(
        &self,
        payload: protocol::SettingsWritePayload,
    ) -> AppResult<protocol::SettingsWriteResultPayload> {
        const OPERATION: &str = "settings_write_for_internal_caller";
        let (queue, mut receiver) = crate::stream::output_channel();
        let stream = Stream::new(StreamPath("/host/internal-settings".to_owned()), queue);
        self.settings_write(payload, &stream).await?;
        let envelope = receiver.try_recv().map_err(|error| {
            AppError::internal_message(OPERATION, "settings write produced no result", error)
        })?;
        envelope.parse_payload().map_err(|error| {
            AppError::internal_message(OPERATION, "failed to parse settings write result", error)
        })
    }

    pub(crate) async fn set_agents_view_preferences(
        &self,
        payload: SetAgentsViewPreferencesPayload,
    ) -> AppResult<()> {
        const OPERATION: &str = "set_agents_view_preferences";
        let response = {
            {
                self.state
                    .with(move |state| {
                        let store =
                            state.agents_view_preferences_store.clone().ok_or_else(|| {
                                AppError::invalid(
                                    OPERATION,
                                    "agents view preferences are owned by the primary local host",
                                )
                            })?;

                        let update = Self::canonicalize_agents_view_preferences_update(
                            state,
                            payload.update,
                        )
                        .map_err(|error| AppError::invalid(OPERATION, error))?;

                        store
                            .enqueue(move |store| store.apply(update))
                            .map_err(|error| AppError::invalid(OPERATION, error))
                    })
                    .await?
            }
        };
        response
            .await
            .map_err(|_| AppError::internal(OPERATION, anyhow!("preferences owner stopped")))?
            .map_err(|error| AppError::invalid(OPERATION, error))?;
        {
            self.state
                .with(move |state| {
                    fan_out_current_agents_view_preferences(state);
                    Ok(())
                })
                .await
        }
    }

