    pub(crate) async fn refresh_backend_setup(&self) {
        let Ok(refresh_guard) = self.backend_setup_refresh_lock.try_lock() else {
            return;
        };
        let payload = self.collect_backend_setup_respecting_probe().await;
        let changed = {
            {
                self.state
                    .with(move |state| {
                        let changed = state.backend_setup != payload;
                        tracing::info!(
                            changed,
                            "refreshed backend installation state for new chat"
                        );
                        fan_out_backend_setup(state, payload);
                        changed
                    })
                    .await
            }
        };
        if changed {
            self.refresh_session_schemas_with_fanout(true).await;
            self.refresh_backend_config_snapshots_with_fanout(true)
                .await;
        }
        drop(refresh_guard);
    }

    pub(crate) async fn fan_out_backend_setup(&self) {
        let payload = self.collect_backend_setup_respecting_probe().await;
        {
            self.state
                .with(move |state| {
                    fan_out_backend_setup(state, payload);
                })
                .await
        }
    }

    /// Collect backend setup, honoring the `skip_real_backend_probe` runtime
    /// flag. When skipping (test fixtures), returns an empty stub instantly
    /// instead of spawning real `<cli> --version` subprocesses and a codex
    /// model-discovery network RPC on every host spawn.
    async fn collect_backend_setup_respecting_probe(&self) -> BackendSetupPayload {
        let (skip, settings_store) = {
            {
                self.state
                    .with(move |state| {
                        (
                            state.skip_real_backend_probe,
                            Arc::clone(&state.settings_store),
                        )
                    })
                    .await
            }
        };
        if skip {
            return setup::stub_backend_setup();
        }
        let settings = settings_store.get().ok();
        let acp_agents = settings
            .as_ref()
            .map(setup::configured_acp_setup_agents)
            .unwrap_or_default();
        setup::collect_backend_setup(&acp_agents).await
    }

