    pub(crate) async fn refresh_session_schema_for_backend(
        &self,
        backend_kind: protocol::BackendKind,
    ) {
        let _refresh_guard = self.session_schema_refresh_lock.lock().await;
        self.refresh_session_schemas_with_fanout_unlocked(false, true, Some(backend_kind))
            .await;
    }

    async fn resolve_session_schema_for_spawn(
        &self,
        backend_kind: protocol::BackendKind,
        profile_id: Option<&LaunchProfileId>,
    ) -> Result<Option<SessionSettingsSchema>, AgentStartupFailure> {
        if !backend_has_dynamic_session_schema(backend_kind) {
            return Ok(Some(session_settings_schema_for_backend(backend_kind)));
        }
        let mut resolution = {
            {
                let profile_id = profile_id.cloned();
                self.state
                    .with(move |state| {
                        session_schema_resolution_for_backend(
                            state,
                            backend_kind,
                            profile_id.as_ref(),
                        )
                    })
                    .await
            }
        };
        if matches!(&resolution, SessionSchemaResolution::Pending) {
            let wait_started = Instant::now();
            let _refresh_guard = self.session_schema_refresh_lock.lock().await;
            tracing::info!(
                ?backend_kind,
                wait_ms = wait_started.elapsed().as_millis(),
                "spawn waited for pending session schema discovery"
            );
            self.refresh_session_schemas_with_fanout_unlocked(false, false, Some(backend_kind))
                .await;
            resolution = {
                {
                    let profile_id = profile_id.cloned();
                    self.state
                        .with(move |state| {
                            session_schema_resolution_for_backend(
                                state,
                                backend_kind,
                                profile_id.as_ref(),
                            )
                        })
                        .await
                }
            };
        }
        match resolution {
            SessionSchemaResolution::Ready(schema) => Ok(Some(schema)),
            SessionSchemaResolution::Unavailable(message) => {
                Err(AgentStartupFailure::backend_failed(format!(
                    "{backend_kind:?} session settings schema unavailable: {message}"
                )))
            }
            SessionSchemaResolution::Pending => Err(AgentStartupFailure::backend_failed(format!(
                "{backend_kind:?} session settings schema unavailable"
            ))),
        }
    }

    async fn refresh_session_schemas_with_fanout(&self, force_emit: bool) {
        let _refresh_guard = self.session_schema_refresh_lock.lock().await;
        self.refresh_session_schemas_with_fanout_unlocked(force_emit, true, None)
            .await;
    }

    async fn refresh_pending_session_discovery(&self) {
        let _refresh_guard = self.session_schema_refresh_lock.lock().await;
        let (enabled, pending) = {
            {
                self.state
                    .with(move |state| {
                        let settings = state
                            .settings_store
                            .get()
                            .expect("load settings for discovery");
                        let pending = settings
                            .enabled_backends
                            .iter()
                            .copied()
                            .filter(|kind| backend_has_dynamic_session_schema(*kind))
                            .filter(|kind| {
                                matches!(
                                    session_schema_resolution_for_backend(state, *kind, None),
                                    SessionSchemaResolution::Pending
                                )
                            })
                            .collect::<HashSet<_>>();
                        (settings.enabled_backends, pending)
                    })
                    .await
            }
        };
        if !pending.is_empty() {
            self.refresh_session_schemas_with_fanout_unlocked(false, false, None)
                .await;
        }
        for kind in enabled {
            if !pending.contains(&kind) && crate::backend::discovery_policy(kind).refresh_on_connect
            {
                self.refresh_session_schemas_with_fanout_unlocked(false, true, Some(kind))
                    .await;
            }
        }
    }

    async fn refresh_session_schemas_with_fanout_unlocked(
        &self,
        force_emit: bool,
        retry_unavailable: bool,
        only: Option<BackendKind>,
    ) {
        let (settings_store, programs, root, disabled, previous, previous_profiles) = {
            {
                self.state
                    .with(move |state| {
                        #[cfg(any(test, feature = "test-support"))]
                        {
                            state.session_schema_probe_count =
                                state.session_schema_probe_count.saturating_add(1);
                        }
                        let previous = state.session_schemas.clone();
                        if retry_unavailable {
                            state
                                .session_schemas
                                .retain(|(kind, _), _| only.is_some_and(|scoped| scoped != *kind));
                        }
                        (
                            Arc::clone(&state.settings_store),
                            state.backend_probe_programs.clone(),
                            state.backend_probe_workspace_root.clone(),
                            state.skip_real_backend_probe,
                            previous,
                            state.discovered_launch_profiles.clone(),
                        )
                    })
                    .await
            }
        };
        let settings = settings_store.get().expect("load settings for discovery");
        let root = backend_probe_workspace_root(root.as_deref());
        let mut schemas = previous.clone();
        let mut profiles = previous_profiles;
        for kind in crate::backend::SUPPORTED_BACKENDS {
            if !backend_has_dynamic_session_schema(kind)
                || only.is_some_and(|scoped| scoped != kind)
            {
                continue;
            }
            if !settings.enabled_backends.contains(&kind) && only != Some(kind) {
                schemas.retain(|(stored, _), _| *stored != kind);
                profiles.remove(&kind);
                continue;
            }
            let policy = crate::backend::discovery_policy(kind);
            let mut keys = vec![discovery_key(kind, None)];
            if policy.profile_scope.is_some() {
                keys.extend(
                    settings
                        .launch_profiles
                        .values()
                        .filter(|profile| {
                            profile.backend_kind == kind
                                && Some(&profile.id) != policy.profile_scope.as_ref()
                        })
                        .map(|profile| discovery_key(kind, Some(&profile.id))),
                );
            }
            schemas.retain(|key, _| key.0 != kind || keys.contains(key));
            for key in keys {
                let prior = previous
                    .get(&key)
                    .cloned()
                    .unwrap_or(SessionSchemaResolution::Pending);
                if !retry_unavailable && !matches!(prior, SessionSchemaResolution::Pending) {
                    continue;
                }
                let custom_profile = key
                    .1
                    .as_ref()
                    .filter(|id| Some(*id) != policy.profile_scope.as_ref());
                let context = crate::backend::BackendProbeContext {
                    #[cfg(any(test, feature = "test-support"))]
                    mock_discovery: {
                        self.state
                            .with(move |state| state.mock_backend_discovery.get(&kind).cloned())
                            .await
                    },
                    workspace_roots: root
                        .as_ref()
                        .map(|root| vec![root.clone()])
                        .unwrap_or_default(),
                    program: custom_profile
                        .is_none()
                        .then(|| programs.get(&kind).cloned())
                        .flatten(),
                    launch: custom_profile
                        .and_then(|id| settings.launch_profiles.get(id))
                        .and_then(|profile| profile.acp.clone()),
                    disabled_providers: settings.hermes_disabled_providers.clone(),
                    session_store: None,
                };
                let is_default_profile = custom_profile.is_none();
                let result = match &root {
                    Err(error) => Err(error.clone()),
                    Ok(_)
                        if disabled
                            && context.program.is_none()
                            && context.launch.is_none()
                            && !context.has_mock_discovery() =>
                    {
                        crate::backend::mock::disabled_discovery(kind, &context)
                    }
                    Ok(_) => crate::backend::discover(kind, &context).await,
                };
                match result {
                    Ok(discovery) => {
                        schemas.insert(key, SessionSchemaResolution::Ready(discovery.schema));
                        if is_default_profile {
                            profiles.insert(kind, discovery.launch_profiles);
                        }
                    }
                    Err(error) => {
                        tracing::error!(?kind, profile = ?key.1, %error, "backend session discovery failed");
                        if policy.retain_last_good
                            && matches!(prior, SessionSchemaResolution::Ready(_))
                        {
                            schemas.insert(key, prior);
                        } else {
                            schemas.insert(key, SessionSchemaResolution::Unavailable(error));
                            if is_default_profile {
                                profiles.remove(&kind);
                            }
                        }
                    }
                }
            }
        }
        {
            self.state
                .with(move |state| {
                    state.session_schemas = schemas;
                    state.discovered_launch_profiles = profiles;
                    fan_out_session_schemas(state, force_emit);
                    fan_out_backend_config_schemas(state);
                    fan_out_launch_profile_catalog(state);
                })
                .await
        }
    }

    async fn refresh_after_backend_setup(&self) {
        let refresh_guard = self.backend_setup_refresh_lock.lock().await;
        for step in BACKEND_SETUP_REFRESH_ORDER {
            match step {
                BackendSetupRefreshStep::Setup => self.fan_out_backend_setup().await,
                BackendSetupRefreshStep::SessionSchemas => {
                    self.refresh_session_schemas_with_fanout(true).await
                }
                BackendSetupRefreshStep::BackendConfigSnapshots => {
                    self.refresh_backend_config_snapshots_with_fanout(true)
                        .await
                }
            }
        }
        drop(refresh_guard);
    }

    pub(crate) async fn run_backend_setup(
        &self,
        connection_host_stream: &StreamPath,
        host_output_stream: &Stream,
        payload: RunBackendSetupPayload,
    ) -> AppResult<()> {
        const OPERATION: &str = "run_backend_setup";
        tracing::info!(
            connection_host_stream = %connection_host_stream,
            host_stream = %host_output_stream.path(),
            backend_kind = ?payload.backend_kind,
            action = ?payload.action,
            "host run_backend_setup requested"
        );
        let prepared = setup::prepare_runnable_command(payload.backend_kind, payload.action)
            .await
            .map_err(|error| AppError::internal(OPERATION, anyhow!(error)))?;
        let Some(prepared) = prepared else {
            return Err(AppError::not_found(
                OPERATION,
                format!(
                    "no runnable backend setup command for {:?} {:?}",
                    payload.backend_kind, payload.action
                ),
            ));
        };

        let cwd = std::env::current_dir()
            .context("failed to resolve backend setup cwd")
            .map_err(|error| AppError::internal(OPERATION, error))?
            .display()
            .to_string();
        let launch = TerminalLaunchInfo {
            execution_project: None,
            project_id: None,
            root: None,
            cwd,
            cols: 100,
            rows: 28,
            command: TerminalLaunchCommand::Trusted {
                program: prepared.program().to_owned(),
                arguments: prepared.arguments().to_vec(),
            },
        };
        let terminal = self
            .create_resolved_terminal_internal(connection_host_stream, host_output_stream, launch)
            .await?;

        if let Some(terminal) = terminal {
            tracing::info!(
                backend_kind = ?payload.backend_kind,
                action = ?payload.action,
                command = %prepared.display_command(),
                "host run_backend_setup launching terminal command"
            );

            let host = self.clone();
            let backend_kind = payload.backend_kind;
            let action = payload.action;
            tokio::spawn(async move {
                let exit = terminal.wait_for_exit().await;
                drop(prepared);
                tracing::info!(
                    backend_kind = ?backend_kind,
                    action = ?action,
                    exit_code = exit.exit_code,
                    signal = exit.signal.as_deref(),
                    "host run_backend_setup terminal exited; refreshing backend state"
                );
                host.refresh_after_backend_setup().await;
            });
        }
        Ok(())
    }

    pub(crate) async fn create_terminal(
        &self,
        connection_host_stream: &StreamPath,
        host_output_stream: &Stream,
        payload: TerminalCreatePayload,
    ) -> AppResult<()> {
        let _ = self
            .create_terminal_internal(connection_host_stream, host_output_stream, payload)
            .await?;
        Ok(())
    }

    async fn create_terminal_internal(
        &self,
        connection_host_stream: &StreamPath,
        host_output_stream: &Stream,
        payload: TerminalCreatePayload,
    ) -> AppResult<Option<TerminalHandle>> {
        let _project_binding = match &payload.target {
            TerminalLaunchTarget::Project { project_id, .. } => Some(
                self.project_catalog
                    .reserve_bindings(vec![project_id.clone()])
                    .await
                    .map_err(|error| AppError::conflict("terminal_create", error))?,
            ),
            _ => None,
        };
        let project_store = {
            {
                self.state
                    .with(move |state| Arc::clone(&state.project_store))
                    .await
            }
        };
        let launch = resolve_terminal_launch(&project_store, payload).await?;
        self.create_resolved_terminal_internal(connection_host_stream, host_output_stream, launch)
            .await
    }

    async fn create_resolved_terminal_internal(
        &self,
        connection_host_stream: &StreamPath,
        host_output_stream: &Stream,
        launch: TerminalLaunchInfo,
    ) -> AppResult<Option<TerminalHandle>> {
        const OPERATION: &str = "terminal_create";
        let launch_project_id = launch.project_id.clone();
        if let Some(project_id) = launch_project_id.clone() {
            self.state.with(move |state| {
                if state.project_store.is_removing(&project_id) {
                    return Err(AppError::conflict(OPERATION, format!(
                        "cannot create terminal in workbench {} because it is being removed", project_id)));
                }
                Ok(())
            }).await?;
        }
        let terminal_id = TerminalId(Uuid::new_v4().to_string());
        let terminal_stream_path = StreamPath(format!("/terminal/{}", terminal_id));
        let terminal_output_stream = host_output_stream.with_path(terminal_stream_path.clone());
        let terminal = create_terminal(launch, terminal_output_stream)
            .await
            .map_err(|error| AppError::internal(OPERATION, anyhow!(error)))?;

        {
            let launch_project_id = launch_project_id.clone();
            let connection_host_stream = connection_host_stream.clone();
            let terminal_id = terminal_id.clone();
            let terminal_stream_path = terminal_stream_path.clone();
            let terminal_for_registration = terminal.clone();
            let registered = self
                .state
                .with(move |state| {
                    if launch_project_id
                        .as_ref()
                        .is_some_and(|id| state.project_store.is_removing(id))
                    {
                        return Ok(false);
                    }
                    let previous = state.terminal_streams.insert(
                        (connection_host_stream, terminal_id),
                        terminal_for_registration,
                    );
                    if previous.is_some() {
                        return Err(AppError::internal_message(
                            OPERATION,
                            format!(
                                "duplicate terminal registration for {}",
                                terminal_stream_path
                            ),
                            anyhow!("duplicate terminal registration"),
                        ));
                    }
                    Ok(true)
                })
                .await?;
            if !registered {
                terminal.close().await;
                return Err(AppError::conflict(
                    OPERATION,
                    "cannot create terminal in a workbench being removed",
                ));
            }
        }

        let host_payload =
            serde_json::to_value(terminal.new_terminal_payload()).map_err(|error| {
                AppError::internal_message(
                    OPERATION,
                    "failed to serialize new terminal payload",
                    error,
                )
            })?;
        if host_output_stream
            .send_value(FrameKind::NewTerminal, host_payload)
            .is_err()
        {
            self.remove_failed_terminal(connection_host_stream, &terminal_id, &terminal)
                .await;
            return Ok(None);
        }
        if terminal.emit_bootstrap_and_start_io().await.is_err() {
            self.remove_failed_terminal(connection_host_stream, &terminal_id, &terminal)
                .await;
            return Ok(None);
        }
        Ok(Some(terminal))
    }

    async fn remove_failed_terminal(
        &self,
        connection_host_stream: &StreamPath,
        terminal_id: &TerminalId,
        terminal: &TerminalHandle,
    ) {
        {
            let connection_host_stream = connection_host_stream.to_owned();
            let terminal_id = terminal_id.to_owned();
            self.state
                .with(move |state| {
                    let connection_host_stream = &connection_host_stream;
                    let terminal_id = &terminal_id;

                    state
                        .terminal_streams
                        .remove(&(connection_host_stream.clone(), terminal_id.clone()));
                })
                .await
        }
        terminal.close().await;
    }

    pub(crate) async fn send_terminal_input(
        &self,
        connection_host_stream: &StreamPath,
        terminal_id: &TerminalId,
        payload: TerminalSendPayload,
    ) -> AppResult<()> {
        let terminal = self
            .terminal_handle(connection_host_stream, terminal_id)
            .await?;
        terminal.send(payload).await;
        Ok(())
    }

    pub(crate) async fn resize_terminal(
        &self,
        connection_host_stream: &StreamPath,
        terminal_id: &TerminalId,
        payload: TerminalResizePayload,
    ) -> AppResult<()> {
        let terminal = self
            .terminal_handle(connection_host_stream, terminal_id)
            .await?;
        terminal.resize(payload.cols, payload.rows).await;
        Ok(())
    }

    pub(crate) async fn close_terminal(
        &self,
        connection_host_stream: &StreamPath,
        terminal_id: &TerminalId,
    ) -> AppResult<()> {
        let terminal = self
            .terminal_handle(connection_host_stream, terminal_id)
            .await?;
        terminal.close().await;
        Ok(())
    }

    pub(crate) async fn agent_handle(&self, agent_id: &AgentId) -> Option<AgentHandle> {
        {
            let agent_id = agent_id.to_owned();
            self.state
                .with(move |state| {
                    let agent_id = &agent_id;
                    state.registry.agent_handle(agent_id)
                })
                .await
        }
    }

    pub(crate) async fn agent_handle_for_instance(
        &self,
        connection_host_stream: &StreamPath,
        target: &protocol::VoiceTarget,
    ) -> Option<AgentHandle> {
        {
            let connection_host_stream = connection_host_stream.to_owned();
            let target = target.to_owned();
            self.state
                .with(move |state| {
                    let connection_host_stream = &connection_host_stream;
                    let target = &target;

                    let subscriber = state.host_streams.get(connection_host_stream)?;
                    let prefix = format!("/agent/{}/", target.agent_id);
                    if !target.instance_stream.0.starts_with(&prefix)
                        || !subscriber
                            .known_agent_streams
                            .contains(&target.instance_stream)
                    {
                        return None;
                    }
                    state.registry.agent_handle(&target.agent_id)
                })
                .await
        }
    }

    pub(crate) async fn load_agent_stream(
        &self,
        connection_host_stream: &StreamPath,
        host_output_stream: &Stream,
        agent_id: AgentId,
        agent_stream: StreamPath,
    ) -> AppResult<()> {
        let (agent_handle, stream) = {
            {
                let agent_id = agent_id.clone();
                let connection_host_stream = connection_host_stream.to_owned();
                let agent_stream = agent_stream.clone();
                let host_output_stream = host_output_stream.to_owned();
                match self.state.with(move |state| {
let connection_host_stream = &connection_host_stream;
let host_output_stream = &host_output_stream;

            let agent_handle = state.registry.agent_handle(&agent_id).ok_or_else(|| {
                AppError::not_found("load_agent", format!("agent {} is not running", agent_id))
            })?;
            let subscriber = state
                .host_streams
                .get_mut(connection_host_stream)
                .ok_or_else(|| {
                    AppError::not_found(
                        "load_agent",
                        format!("host stream {} is not registered", connection_host_stream),
                    )
                })?;
            if !subscriber.known_agent_streams.contains(&agent_stream) {
                return Ok(std::ops::ControlFlow::Break(Err(AppError::not_found(
                    "load_agent",
                    format!(
                        "agent stream {} was not advertised on host stream {}",
                        agent_stream, connection_host_stream
                    ),
                ))));
            }
            if subscriber.attached_agent_streams.contains(&agent_stream) {
                return Ok(std::ops::ControlFlow::Break(Err(AppError::conflict(
                    "load_agent",
                    format!(
                        "agent stream {} is already attached; reconnect to retry loading the agent",
                        agent_stream
                    ),
                ))));
            }
            subscriber
                .attached_agent_streams
                .insert(agent_stream.clone());

Ok::<_, AppError>(std::ops::ControlFlow::Continue((
                agent_handle,
                host_output_stream.with_path(agent_stream.clone()),
            )))

}).await? { std::ops::ControlFlow::Break(result) => return result, std::ops::ControlFlow::Continue(value) => value }
            }
        };

        if agent_handle.attach(stream).await {
            {
                let connection_host_stream = connection_host_stream.to_owned();
                let agent_stream = agent_stream.clone();
                self.state
                    .with(move |state| {
                        let connection_host_stream = &connection_host_stream;

                        if let Some(subscriber) = state.host_streams.get_mut(connection_host_stream)
                        {
                            subscriber
                                .bootstrapped_agent_streams
                                .insert(agent_stream.clone());
                        }
                        Ok(())
                    })
                    .await
            }
        } else {
            {
                let connection_host_stream = connection_host_stream.to_owned();
                self.state
                    .with(move |state| {
                        let connection_host_stream = &connection_host_stream;

                        if let Some(subscriber) = state.host_streams.get_mut(connection_host_stream)
                        {
                            subscriber.attached_agent_streams.remove(&agent_stream);
                            subscriber.bootstrapped_agent_streams.remove(&agent_stream);
                        }
                        Err(AppError::not_found(
                            "load_agent",
                            format!("agent {} is not running", agent_id),
                        ))
                    })
                    .await
            }
        }
    }

    pub(crate) async fn fetch_session_history(
        &self,
        connection_host_stream: &StreamPath,
        host_output_stream: &Stream,
        agent_stream: StreamPath,
        payload: protocol::FetchSessionHistoryPayload,
    ) -> AppResult<()> {
        if payload.limit == 0 {
            return Err(AppError::invalid(
                "fetch_session_history",
                "limit must be greater than zero",
            ));
        }

        let agent_handle = {
            {
                let connection_host_stream = connection_host_stream.to_owned();
                let agent_stream = agent_stream.clone();
                let payload = payload.clone();
                match self.state.with(move |state| {
let connection_host_stream = &connection_host_stream;

            let subscriber = state
                .host_streams
                .get(connection_host_stream)
                .ok_or_else(|| {
                    AppError::not_found(
                        "fetch_session_history",
                        format!("host stream {} is not registered", connection_host_stream),
                    )
                })?;
            if !subscriber.known_agent_streams.contains(&agent_stream) {
                return Ok(std::ops::ControlFlow::Break(Err(AppError::not_found(
                    "fetch_session_history",
                    format!(
                        "agent stream {} was not advertised on host stream {}",
                        agent_stream, connection_host_stream
                    ),
                ))));
            }
            if !subscriber
                .bootstrapped_agent_streams
                .contains(&agent_stream)
            {
                return Ok(std::ops::ControlFlow::Break(Err(AppError::invalid(
                    "fetch_session_history",
                    format!(
                        "agent stream {} has not completed AgentBootstrap on host stream {}",
                        agent_stream, connection_host_stream
                    ),
                ))));
            }

Ok::<_, AppError>(std::ops::ControlFlow::Continue(state
                .registry
                .agent_handle(&payload.agent_id)
                .ok_or_else(|| {
                    AppError::not_found(
                        "fetch_session_history",
                        format!("agent {} is not running", payload.agent_id),
                    )
                })?))

}).await? { std::ops::ControlFlow::Break(result) => return result, std::ops::ControlFlow::Continue(value) => value }
            }
        };

        let requested_before_seq = payload.before_seq;
        let request_id = payload.request_id;
        let Some(window) = agent_handle
            .fetch_session_history(requested_before_seq, payload.limit as usize)
            .await
        else {
            return Err(AppError::not_found(
                "fetch_session_history",
                format!("agent {} is not running", payload.agent_id),
            ));
        };

        let response = SessionHistoryPayload {
            agent_id: payload.agent_id,
            request_id,
            request_before_seq: requested_before_seq,
            events: window.events,
            has_more_before: window.has_more_before,
            oldest_seq: window.oldest_seq,
        };
        let response = serde_json::to_value(response)
            .map_err(|error| AppError::internal("fetch_session_history", error))?;
        host_output_stream
            .with_path(agent_stream)
            .send_value(FrameKind::SessionHistory, response)
            .map_err(|_| AppError::internal("fetch_session_history", anyhow!("stream closed")))
    }

    pub(crate) async fn config_mcp_caller(
        &self,
        parts: &axum::http::request::Parts,
    ) -> Result<Option<AgentId>, String> {
        {
            let parts = parts.to_owned();
            self.state
                .with(move |state| {
                    let parts = &parts;
                    state.agent_control_mcp.authenticate(parts)
                })
                .await
        }
    }

    pub(crate) async fn tyde_permissions_for_caller(
        &self,
        caller: Option<&AgentId>,
    ) -> Result<protocol::AgentTydePermissions, String> {
        match caller {
            Some(id) => self
                .agent_handle(id)
                .await
                .map(|handle| handle.snapshot().tyde_permissions)
                .ok_or_else(|| "Tyde permission caller is no longer live".to_owned()),
            None => Ok(protocol::AgentTydePermissions::Root),
        }
    }

    pub(crate) async fn list_steering(&self) -> Result<Vec<protocol::Steering>, String> {
        {
            self.state
                .with(move |state| state.steering_store.list())
                .await
        }
    }

    pub(crate) async fn agent_message_origin(
        &self,
        agent_id: &AgentId,
    ) -> Result<protocol::MessageOrigin, String> {
        let handle = self
            .agent_handle(agent_id)
            .await
            .ok_or_else(|| "Message sender is no longer live".to_owned())?;
        let start = handle.snapshot();
        Ok(protocol::MessageOrigin::Agent {
            agent_id: Some(start.agent_id),
            name: start.name,
        })
    }

    pub(crate) async fn set_agent_tyde_permissions(
        &self,
        agent_id: &AgentId,
        access: protocol::AgentTydePermissions,
    ) -> Result<(), String> {
        let handle = self
            .agent_handle(agent_id)
            .await
            .ok_or_else(|| "Agent is no longer live".to_owned())?;
        handle.set_tyde_permissions(access).await?;
        {
            let agent_id = agent_id.to_owned();
            self.state
                .with(move |state| {
                    let agent_id = &agent_id;

                    let payload = protocol::AgentTydePermissionsChangedPayload {
                        agent_id: agent_id.clone(),
                        access: handle.snapshot().tyde_permissions,
                    };
                    let payload =
                        serde_json::to_value(payload).map_err(|error| error.to_string())?;
                    let prefix = format!("/agent/{agent_id}/");
                    let mut dead_paths = Vec::new();
                    for (path, subscriber) in state.host_streams.iter_mut() {
                        let Some(stream) = subscriber
                            .known_agent_streams
                            .iter()
                            .find(|stream| stream.0.starts_with(&prefix))
                        else {
                            continue;
                        };
                        if subscriber.attached_agent_streams.contains(stream) {
                            continue;
                        }
                        if emit_or_queue_host_frame(
                            subscriber,
                            FrameKind::AgentTydePermissionsChanged,
                            payload.clone(),
                        )
                        .is_err()
                        {
                            dead_paths.push(path.clone());
                        }
                    }
                    for path in dead_paths {
                        state.host_streams.remove(&path);
                    }
                    Ok(())
                })
                .await
        }
    }

    pub(crate) async fn interrupt_agent(&self, agent_id: &AgentId) -> InterruptOutcome {
        let (agent_handle, agent_control_mcp) = {
            {
                let agent_id = agent_id.to_owned();
                self.state
                    .with(move |state| {
                        let agent_id = &agent_id;

                        (
                            state.registry.agent_handle(agent_id),
                            state.agent_control_mcp.clone(),
                        )
                    })
                    .await
            }
        };

        agent_control_mcp.cancel_await_requests_for(agent_id);

        match agent_handle {
            Some(handle) => handle.interrupt().await,
            None => InterruptOutcome::NotRunning,
        }
    }

    /// Stop one still-running background command on this agent.
    ///
    /// Scoped to the single card the user cancelled: the turn is untouched and
    /// any other background work keeps running.
    pub(crate) async fn cancel_background_task(
        &self,
        agent_id: &AgentId,
        tool_call_id: &str,
    ) -> crate::backend::CancelBackgroundTaskOutcome {
        let agent_handle = {
            {
                let agent_id = agent_id.to_owned();
                self.state
                    .with(move |state| {
                        let agent_id = &agent_id;

                        state.registry.agent_handle(agent_id)
                    })
                    .await
            }
        };
        match agent_handle {
            Some(handle) => handle.cancel_background_task(tool_call_id).await,
            None => crate::backend::CancelBackgroundTaskOutcome::NotTracked,
        }
    }

    async fn cleanup_unclaimed_agent(&self, agent_id: AgentId) -> AppResult<()> {
        let result = self
            .close_agent_with_publication(
                &agent_id,
                true,
                None,
                AgentCloseIntent::UnclaimedCreation,
            )
            .await;
        let result = match result {
            Ok(true) => Ok(()),
            Ok(false) => {
                let id = agent_id.clone();
                if self
                    .state
                    .with(move |state| state.registry.agent_handle(&id).is_some())
                    .await
                {
                    Err(AppError::conflict(
                        "cancel_unclaimed_agent",
                        "Unclaimed agent cleanup is still owned by an active close",
                    ))
                } else {
                    Ok(())
                }
            }
            Err(error) => Err(AppError::internal_message(
                "cancel_unclaimed_agent",
                format!("Cannot finish cleanup of an unclaimed agent: {error}"),
                anyhow!(error),
            )),
        };
        if let Err(error) = &result {
            tracing::error!(%error, "Unclaimed agent cleanup remains owned by the host");
            let payload = error.to_payload(new_instance_stream(&agent_id), FrameKind::SpawnAgent);
            self.state
                .with_required(move |state| {
                    if state.registry.agent_handle(&agent_id).is_none() {
                        return;
                    }
                    state
                        .unclaimed_agent_cleanup_failures
                        .insert(agent_id, payload.clone());
                    let payload =
                        serde_json::to_value(payload).expect("CommandError payload serializes");
                    let dead_paths = state
                        .host_streams
                        .iter_mut()
                        .filter_map(|(path, subscriber)| {
                            emit_or_queue_host_frame(
                                subscriber,
                                FrameKind::CommandError,
                                payload.clone(),
                            )
                            .err()
                            .map(|_| path.clone())
                        })
                        .collect::<Vec<_>>();
                    for path in dead_paths {
                        state.host_streams.remove(&path);
                        state.agent_visibility.remove_host_stream(&path);
                        state.mobile_access.unregister_subscriber(path);
                    }
                })
                .await;
            self.fan_out_task_token_usages().await;
        }
        result
    }

    #[cfg(feature = "test-support")]
    pub async fn wait_for_agent_startup_for_test(&self, agent_id: &AgentId) -> Result<(), String> {
        let id = agent_id.clone();
        let handle = self
            .state
            .with(move |state| state.registry.agent_handle(&id))
            .await
            .ok_or("agent was removed before startup")?;
        handle
            .wait_for_swarm_startup_ready()
            .await
            .map(|_| ())
            .map_err(|_| "agent startup failed".into())
    }

    pub(crate) async fn close_agent(&self, agent_id: &AgentId) -> AppResult<bool> {
        let is_tychat = {
            let agent_id = agent_id.to_owned();
            self.state
                .with(move |state| {
                    let agent_id = &agent_id;
                    state
                        .registry
                        .agent_handle(agent_id)
                        .is_some_and(|handle| handle.snapshot().origin == AgentOrigin::Tychat)
                })
                .await
        };
        if is_tychat {
            return Ok(false);
        }
        self.close_agent_with_host_visibility(agent_id, false).await
    }

    async fn close_agent_for_recorded_visibility(&self, agent_id: &AgentId) -> AppResult<bool> {
        let close_ids = {
            {
                let agent_id = agent_id.to_owned();
                self.state
                    .with(move |state| {
                        let agent_id = &agent_id;

                        state
                            .registry
                            .agent_subtree_post_order(agent_id)
                            .into_iter()
                            .map(|(agent_id, _)| agent_id)
                            .collect::<Vec<_>>()
                    })
                    .await
            }
        };
        let mut closed = false;
        for close_id in close_ids {
            closed |= self
                .close_agent_with_host_visibility(&close_id, true)
                .await?;
        }
        Ok(closed)
    }

    async fn close_agent_with_host_visibility(
        &self,
        agent_id: &AgentId,
        recorded_visibility_only: bool,
    ) -> AppResult<bool> {
        self.close_agent_with_publication(
            agent_id,
            recorded_visibility_only,
            None,
            AgentCloseIntent::User,
        )
        .await
    }

    async fn close_agent_with_publication(
        &self,
        agent_id: &AgentId,
        recorded_visibility_only: bool,
        completed_compaction: Option<(Stream, AgentCompactNotifyPayload)>,
        intent: AgentCloseIntent,
    ) -> AppResult<bool> {
        let (
            close_targets,
            session_store,
            closing_sessions_by_agent,
            backend_storage,
            close_preparations,
        ) = {
            {
                let agent_id = agent_id.to_owned();
                match self.state.with(move |state| {
let agent_id = &agent_id;

            let close_targets = state.registry.agent_subtree_post_order(agent_id);
            if close_targets.is_empty() {
                return Ok(std::ops::ControlFlow::Break(Ok(false)));
            }
            if state
                .registry
                .agent_handle(agent_id)
                .is_some_and(|handle| handle.is_close_preparing())
            {
                return Ok(std::ops::ControlFlow::Break(Ok(false)));
            }
            let close_preparations = close_targets.iter().map(|(_, handle)| handle.prepare_close().ok_or_else(|| AppError::conflict("close_agent", "A descendant is already closing; finish that close before closing this subtree"))).collect::<AppResult<Vec<_>>>()?;
            let closing_sessions_by_agent = close_targets
                .iter()
                .filter_map(|(agent_id, handle)| {
                    state
                        .agent_sessions
                        .get(agent_id)
                        .or_else(|| state.pending_agent_sessions.get(agent_id))
                        .cloned()
                        .or_else(|| handle.snapshot().session_id)
                        .map(|session_id| (agent_id.clone(), session_id))
                })
                .collect::<HashMap<_, _>>();

Ok::<_, AppError>(std::ops::ControlFlow::Continue((
                close_targets,
                Arc::clone(&state.session_store),
                closing_sessions_by_agent,
                state.backend_storage.clone(),
                close_preparations,
            )))

}).await? { std::ops::ControlFlow::Break(result) => return result, std::ops::ControlFlow::Continue(value) => value }
            }
        };
        let reviews = {
            self.state
                .with(move |state| state.review_registry.clone())
                .await
        };
        for (id, _) in &close_targets {
            if let Err(error) = reviews.reviewer_closed(id.clone()) {
                tracing::warn!(%error, "failed to record reviewer closure");
            }
        }
        let closing_session_ids = closing_sessions_by_agent
            .values()
            .cloned()
            .collect::<HashSet<_>>();
        let close_ids = close_targets
            .iter()
            .map(|(agent_id, _)| agent_id.clone())
            .collect::<Vec<_>>();
        if intent == AgentCloseIntent::User {
            self.withdraw_unowned_restoration_markers(
                &closing_session_ids,
                &session_store,
                "closing subtree",
            )
            .await?;
        }
        for (_, agent_handle) in &close_targets {
            agent_handle.begin_closing();
        }
        if intent == AgentCloseIntent::UnclaimedCreation {
            // There is no caller left to retain a running agent on a storage error.
            for (_, agent_handle) in &close_targets {
                let acknowledged = agent_handle.close().await;
                tracing::debug!(acknowledged, "unclaimed actor stop command settled");
            }
            self.withdraw_unowned_restoration_markers(
                &closing_session_ids,
                &session_store,
                "unclaimed creation",
            )
            .await?;
        }
        let mut closed_usage_snapshots = Vec::new();
        for (_, agent_handle) in &close_targets {
            // Recovery I/O belongs to its own actor, not the suspended startup
            // future. Wait for teardown instead of announcing a timed-out close.
            if intent == AgentCloseIntent::User {
                let acknowledged = agent_handle.close().await;
                tracing::debug!(acknowledged, "agent close command settled");
            }
            let mut snapshot = agent_handle
                .final_usage_snapshot()
                .map_err(|error| AppError::internal("close_agent", anyhow!(error)))?;
            snapshot.navigation = protocol::TaskUsageNavigation::Unavailable;
            if let Some(session_id) = snapshot.start.session_id.as_ref() {
                let session = session_id.clone();
                let storage = backend_storage.clone();
                let resumable = session_store
                    .read(move |store| {
                        Ok(store
                            .get_result(&session)?
                            .is_some_and(|record| session_record_is_resumable(&record, &storage)))
                    })
                    .await
                    .map_err(|error| {
                        AppError::internal(
                            "close_agent",
                            anyhow!("Cannot read saved task context: {error}"),
                        )
                    })?;
                if resumable {
                    snapshot.navigation = protocol::TaskUsageNavigation::SavedSession {
                        session_id: session_id.clone(),
                    };
                }
            }
            session_store
                .save_task_usage_snapshot(snapshot.clone())
                .await
                .map_err(|error| {
                    AppError::internal(
                        "close_agent",
                        anyhow!("Cannot save settled task accounting: {error}"),
                    )
                })?;
            closed_usage_snapshots.push(snapshot);
        }
        {
            {
                self.state
                    .with(move |state| {
                        for snapshot in closed_usage_snapshots {
                            if let Some(session) = &snapshot.start.session_id {
                                state.closed_agent_usage_snapshots.retain(|_, saved| {
                                    saved.start.session_id.as_ref() != Some(session)
                                });
                            }
                            state
                                .closed_agent_usage_snapshots
                                .insert(snapshot.start.agent_id.clone(), snapshot);
                        }
                    })
                    .await
            }
        }
        for (target_agent_id, agent_handle) in &close_targets {
            let mut settled_session_ids = closing_sessions_by_agent
                .get(target_agent_id)
                .cloned()
                .into_iter()
                .collect::<HashSet<_>>();
            settled_session_ids.extend(agent_handle.snapshot().session_id);
            self.withdraw_unowned_restoration_markers(
                &settled_session_ids,
                &session_store,
                "settled close",
            )
            .await?;
        }
        let mut cleanup_events = Vec::new();
        for closed_agent_id in &close_ids {
            let (parent, remove_annotations, annotations, teams, swarms) = {
                {
                    let closed_agent_id = closed_agent_id.to_owned();
                    self.state
                        .with(move |state| {
                            let closed_agent_id = &closed_agent_id;

                            let snapshot_session = state
                                .registry
                                .agent_handle(closed_agent_id)
                                .and_then(|agent| agent.snapshot().session_id);
                            let remove_annotations =
                                state.pending_agent_sessions.contains_key(closed_agent_id)
                                    || state
                                        .agent_sessions
                                        .get(closed_agent_id)
                                        .cloned()
                                        .or(snapshot_session)
                                        .is_none();
                            (
                                state.registry.parent_agent_id(closed_agent_id),
                                remove_annotations,
                                state.agents_view_preferences_store.clone(),
                                state.team_registry.clone(),
                                state.swarm_registry.clone(),
                            )
                        })
                        .await
                }
            };
            let session = closing_sessions_by_agent.get(closed_agent_id).cloned();
            let member = close_targets
                .iter()
                .find(|(id, _)| id == closed_agent_id)
                .is_some_and(|(_, handle)| handle.snapshot().swarm_membership.is_some());
            let swarm_events = if member {
                swarms
                    .status(
                        closed_agent_id.clone(),
                        AgentControlStatus::Idle,
                        session,
                        true,
                        None,
                    )
                    .await
                    .map_err(|error| AppError::internal("close_agent", anyhow!(error.message)))?
            } else {
                Vec::new()
            };
            if remove_annotations && let Some(store) = annotations {
                let agent = closed_agent_id.clone();
                store
                    .call(move |store| {
                        store.remove_transient_agent(HostFilterId(LOCAL_HOST_ID.to_owned()), agent)
                    })
                    .await
                    .map_err(|error| AppError::internal("close_agent", anyhow!(error)))?;
            }
            let team_events = teams
                .clear_binding_by_agent(closed_agent_id.clone())
                .await
                .map_err(|error| AppError::internal("close_agent", anyhow!(error)))?;
            cleanup_events.push((closed_agent_id.clone(), parent, swarm_events, team_events));
        }
        self.fan_out_session_lists().await?;
        for preparation in close_preparations {
            preparation.commit();
        }
        let parents = {
            {
                self.state
                    .with(move |state| {
                        let mut parents = Vec::new();
                        if let Some((stream, completed)) = completed_compaction {
                            send_agent_compact_notify(&stream, completed);
                        }
                        let mut dead_paths = Vec::new();
                        for (closed_agent_id, parent, swarm_events, team_events) in cleanup_events {
                            let visible = recorded_visibility_only.then(|| {
                                state
                                    .agent_visibility
                                    .visible_host_streams(&closed_agent_id)
                            });
                            let payload = serde_json::to_value(AgentClosedPayload {
                                agent_id: closed_agent_id.clone(),
                            })
                            .map_err(|error| AppError::internal("close_agent", anyhow!(error)))?;
                            for (path, subscriber) in &mut state.host_streams {
                                if visible.as_ref().is_none_or(|paths| paths.contains(path))
                                    && emit_or_queue_host_frame(
                                        subscriber,
                                        FrameKind::AgentClosed,
                                        payload.clone(),
                                    )
                                    .is_err()
                                {
                                    dead_paths.push(path.clone());
                                }
                            }
                            let removed = state.registry.remove_agent(&closed_agent_id).is_some();
                            tracing::debug!(
                                removed,
                                registry_agent_count = state.registry.agent_ids().len(),
                                "canonical close registry transition"
                            );
                            state.agent_visibility.remove_agent(&closed_agent_id);
                            state
                                .unclaimed_agent_cleanup_failures
                                .remove(&closed_agent_id);
                            state.spawn_publication_claims.remove(&closed_agent_id);
                            state.agent_sessions.remove(&closed_agent_id);
                            state.pending_agent_sessions.remove(&closed_agent_id);
                            state
                                .pending_session_summary_count_updates
                                .remove(&closed_agent_id);
                            state.agent_activity_summaries.remove(&closed_agent_id);
                            for subscriber in state.host_streams.values_mut() {
                                forget_agent_fanout_for_subscriber(subscriber, &closed_agent_id);
                                subscriber.last_task_token_usages.clear();
                            }
                            swarms::fan_out_swarm_events_locked(state, swarm_events);
                            fan_out_team_registry_events(state, team_events);
                            if let Some(parent) = parent {
                                parents.push(parent);
                            }
                        }

                        for path in dead_paths {
                            state.host_streams.remove(&path);
                            state.agent_visibility.remove_host_stream(&path);
                        }
                        Ok::<_, AppError>(parents)
                    })
                    .await?
            }
        };
        self.restart
            .agents
            .lock()
            .expect("restart handles mutex poisoned")
            .retain(|handle| !close_ids.contains(&handle.snapshot().agent_id));
        for parent in parents {
            self.publish_agent_background_work(&parent).await;
        }
        {
            {
                self.state
                    .with(move |state| {
                        fan_out_current_agents_view_preferences(state);
                    })
                    .await
            }
        }
        self.fan_out_task_token_usages().await;
        Ok(true)
    }

