    fn resume_parent_owner<'a>(
        &'a self,
        child: &'a SessionRecord,
    ) -> futures_util::future::BoxFuture<'a, AppResult<AgentId>> {
        async move {
            let (store, storage, teams) = {
                {
                    self.state
                        .with(move |state| {
                            (
                                Arc::clone(&state.session_store),
                                state.backend_storage.clone(),
                                state.team_registry.clone(),
                            )
                        })
                        .await
                }
            };
            let mut ancestors = Vec::new();
            let mut visited = HashSet::from([child.id.clone()]);
            let mut next = child.parent_id.clone();
            while let Some(session_id) = next {
                if !visited.insert(session_id.clone()) {
                    return Err(AppError::conflict(
                        "spawn_agent",
                        "saved parent lineage contains a cycle",
                    ));
                }
                let record = store.get(&session_id).await.ok_or_else(|| {
                    AppError::not_found("spawn_agent", "saved parent session is missing")
                })?;
                next = record.parent_id.clone();
                ancestors.push(record);
            }
            let team_snapshot = teams
                .snapshot()
                .await
                .map_err(|error| AppError::internal("spawn_agent", anyhow!(error)))?;
            let mut parent_agent_id = None;
            for ancestor in ancestors.into_iter().rev() {
                let admitted = self.session_resume_admission(&ancestor.id).await;
                if let Some(owner) = self.live_agent_for_session(&ancestor.id).await {
                    parent_agent_id = Some(owner);
                    continue;
                }
                let record = store.get(&ancestor.id).await.ok_or_else(|| {
                    AppError::not_found("spawn_agent", "saved parent session was removed")
                })?;
                let restore = record.restore_state.as_ref().ok_or_else(|| {
                    AppError::conflict(
                        "spawn_agent",
                        "owning parent is closed; resume the parent first",
                    )
                })?;
                if !session_record_is_resumable(&record, &storage) {
                    return Err(AppError::conflict(
                        "spawn_agent",
                        "owning parent session cannot be resumed",
                    ));
                }
                let team_context = team_snapshot.members.iter().find_map(|member| {
                    (member.session_id.as_ref() == Some(&record.id)).then(|| TeamSpawnContext {
                        team_id: member.team_id.clone(),
                        team_member_id: member.id.clone(),
                    })
                });
                tracing::info!(
                    ancestor_count = visited.len().saturating_sub(1),
                    "resuming saved parent before admitting its child"
                );
                let owner = self
                    .spawn_agent_with_origin_config_and_team(
                        SpawnAgentPayload {
                            launch_context: protocol::AgentLaunchContext::Standard,
                            name: None,
                            custom_agent_id: record.custom_agent_id.clone(),
                            parent_agent_id,
                            project_id: record.project_id.clone(),
                            params: SpawnAgentParams::Resume {
                                session_id: record.id.clone(),
                                prompt: None,
                            },
                        },
                        SpawnAgentContext {
                            origin: restore.origin,
                            workflow: restore.workflow.clone(),
                            team_context: team_context.clone(),
                            admitted_session: Some(admitted),
                            ..Default::default()
                        },
                    )
                    .await?;
                if let Some(team_context) = team_context {
                    self.bind_restored_team_member(team_context, owner.clone(), record.id)
                        .await;
                }
                parent_agent_id = Some(owner);
            }
            parent_agent_id
                .ok_or_else(|| AppError::conflict("spawn_agent", "saved parent lineage is empty"))
        }
        .boxed()
    }

    async fn live_agent_for_session(&self, session_id: &SessionId) -> Option<AgentId> {
        let session_id = session_id.clone();
        self.state
            .with(move |state| live_session_owner(state, &session_id))
            .await
    }

    // Resume ownership publication and marker withdrawal share reservations,
    // not the longer admission phase: a close must not wait for discovery.
    async fn withdraw_unowned_restoration_markers(
        &self,
        sessions: &HashSet<SessionId>,
        session_store: &Arc<SessionStoreHandle>,
        context: &'static str,
    ) -> AppResult<()> {
        if sessions.is_empty() {
            return Ok(());
        }
        let (orphaned, _claims) = loop {
            let sessions = sessions.clone();
            let outcome = self
                .state
                .with(move |state| {
                    state
                        .withdrawing_sessions
                        .retain(|_, claim| !claim.is_cancelled());
                    if let Some(active) = sessions
                        .iter()
                        .find_map(|id| state.withdrawing_sessions.get(id).cloned())
                    {
                        return std::ops::ControlFlow::Break(active);
                    }
                    let mut orphaned = HashSet::new();
                    let mut claims = Vec::with_capacity(sessions.len());
                    for session_id in &sessions {
                        let resuming = state
                            .resuming_sessions
                            .get(session_id)
                            .is_some_and(|claims| claims.iter().any(|claim| !claim.is_cancelled()));
                        if live_session_owner(state, session_id).is_none() && !resuming {
                            orphaned.insert(session_id.clone());
                        }
                        let claim = CancellationToken::new();
                        state
                            .withdrawing_sessions
                            .insert(session_id.clone(), claim.clone());
                        claims.push(claim.drop_guard());
                    }
                    std::ops::ControlFlow::Continue((orphaned, claims))
                })
                .await;
            match outcome {
                std::ops::ControlFlow::Continue(claims) => break claims,
                std::ops::ControlFlow::Break(active) => active.cancelled().await,
            }
        };
        #[cfg(feature = "test-support")]
        {
            let gate = {
                self.state
                    .with(move |state| state.restore_marker_withdraw_test_gate.clone())
                    .await
            };
            if let Some(gate) = gate {
                eprintln!(
                    "Close withdrawal diagnostic: phase=gate-entered context={context} orphaned_count={}",
                    orphaned.len()
                );
                wait_for_spawn_operation_test_gate_inner(&gate).await;
                eprintln!("Close withdrawal diagnostic: phase=gate-released context={context}");
            }
        }
        if !orphaned.is_empty() {
            session_store
                .clear_restore_states(&orphaned)
                .await
                .map_err(|error| {
                    AppError::internal(
                        "close_agent",
                        anyhow!(
                            "Cannot clear closed task restoration markers ({context}): {error}"
                        ),
                    )
                })?;
        }
        Ok(())
    }

    pub(crate) async fn withdraw_failed_project_entry_restoration(
        &self,
        agent_id: &AgentId,
    ) -> Result<(), String> {
        let (handle, store) = {
            {
                let agent_id = agent_id.to_owned();
                self.state
                    .with(move |state| {
                        let agent_id = &agent_id;

                        let handle = state.registry.agent_handle(agent_id).ok_or_else(|| {
                            "Conversation disappeared before project entry retirement".to_owned()
                        })?;

                        Ok::<_, String>((handle, state.session_store.clone()))
                    })
                    .await?
            }
        };
        // The entry actor is waiting for this durable phase: close admission
        // must not request work from that same agent.
        handle.begin_closing();
        let session = handle
            .snapshot()
            .session_id
            .ok_or_else(|| "Failed project entry has no canonical session".to_owned())?;
        self.withdraw_unowned_restoration_markers(
            &HashSet::from([session]),
            &store,
            "failed project entry",
        )
        .await
        .map_err(|error| error.message)
    }

    async fn session_resume_admission(
        &self,
        session_id: &SessionId,
    ) -> tokio_util::sync::DropGuard {
        loop {
            let session_id = session_id.clone();
            let outcome = self
                .state
                .with(move |state| {
                    state
                        .session_resume_admission
                        .retain(|_, claim| !claim.is_cancelled());
                    state
                        .deleting_sessions
                        .retain(|_, claim| !claim.is_cancelled());
                    if let Some(active) = state
                        .deleting_sessions
                        .get(&session_id)
                        .or_else(|| state.session_resume_admission.get(&session_id))
                        .cloned()
                    {
                        return Err(active);
                    }
                    let claim = CancellationToken::new();
                    state
                        .session_resume_admission
                        .insert(session_id.clone(), claim.clone());
                    Ok(claim.drop_guard())
                })
                .await;
            match outcome {
                Ok(claim) => return claim,
                Err(active) => active.cancelled().await,
            }
        }
    }

    async fn claim_inflight_resume(
        &self,
        session_id: &SessionId,
        require_restore_intent: bool,
    ) -> AppResult<InflightResumeClaim> {
        let (ownership, store) = loop {
            let session_id = session_id.clone();
            let outcome = self
                .state
                .with(move |state| {
                    if state
                        .deleting_sessions
                        .get(&session_id)
                        .is_some_and(|claim| !claim.is_cancelled())
                    {
                        return Err(AppError::conflict(
                            "spawn_agent",
                            "This session is being deleted",
                        ));
                    }
                    if let Some(active) = state
                        .withdrawing_sessions
                        .get(&session_id)
                        .filter(|claim| !claim.is_cancelled())
                        .cloned()
                    {
                        return Ok(std::ops::ControlFlow::Break(active));
                    }
                    state.resuming_sessions.retain(|_, claims| {
                        claims.retain(|claim| !claim.is_cancelled());
                        !claims.is_empty()
                    });
                    let claim = CancellationToken::new();
                    state
                        .resuming_sessions
                        .entry(session_id.clone())
                        .or_default()
                        .push(claim.clone());
                    Ok::<_, AppError>(std::ops::ControlFlow::Continue((
                        claim.drop_guard(),
                        Arc::clone(&state.session_store),
                    )))
                })
                .await?;
            match outcome {
                std::ops::ControlFlow::Continue(ownership) => break ownership,
                std::ops::ControlFlow::Break(active) => active.cancelled().await,
            }
        };
        if require_restore_intent {
            let id = session_id.clone();
            let wanted = store
                .read(move |store| {
                    Ok(store
                        .get_result(&id)?
                        .is_some_and(|record| record.restore_state.is_some()))
                })
                .await
                .map_err(|error| AppError::internal("spawn_agent", anyhow!(error)))?;
            if !wanted {
                return Err(AppError::conflict(
                    "spawn_agent",
                    "This session is no longer marked for restoration",
                ));
            }
        }
        Ok(ownership)
    }

