    async fn validate_sub_agent_depth(&self, parent_agent_id: &AgentId) -> Result<(), String> {
        let (parent_depth, settings_store) = {
            {
                let parent_agent_id = parent_agent_id.to_owned();
                self.state
                    .with(move |state| {
                        let parent_agent_id = &parent_agent_id;

                        let parent_depth =
                            state.registry.agent_depth(parent_agent_id).ok_or_else(|| {
                                format!(
                                    "cannot determine agent-control depth for {parent_agent_id}"
                                )
                            })?;

                        Ok::<_, String>((parent_depth, Arc::clone(&state.settings_store)))
                    })
                    .await?
            }
        };
        let max_depth = settings_store
            .get()
            .map_err(|error| format!("failed to load host settings: {error}"))?
            .tyde_agent_control_max_depth;
        if parent_depth >= max_depth {
            return Err(format!(
                "Tyde sub-agent depth limit of {max_depth} reached; agent {parent_agent_id} cannot spawn another level"
            ));
        }
        Ok(())
    }

    /// Spawn an agent from agent-control MCP, inheriting workflow context and
    /// project ownership from the calling or parent agent when applicable.
    pub(crate) async fn spawn_agent_from_agent_control(
        &self,
        mut payload: SpawnAgentPayload,
        caller_agent_id: Option<&AgentId>,
        input_origin: protocol::MessageOrigin,
    ) -> Result<AgentId, String> {
        if let Some(parent_agent_id) = payload.parent_agent_id.as_ref().or(caller_agent_id) {
            if self
                .is_swarm_agent(parent_agent_id)
                .await
                .map_err(|error| error.message)?
            {
                return Err("Swarm members cannot spawn children".into());
            }
            self.validate_sub_agent_depth(parent_agent_id).await?;
        }
        // A closing agent must not grow the subtree being torn down.
        // `close_agent` snapshots the subtree once, so a child spawned after
        // that snapshot is never part of the teardown: it outlives the parent
        // that owns it and nothing subsequently closes it.
        //
        // A registered, merely terminated parent is different: parked actors
        // still host a valid agent-control caller. An in-progress teardown has
        // a subtree snapshot that a new child can escape, while an absent
        // parent has no subtree to own the child.
        if let Some(parent_agent_id) = payload.parent_agent_id.as_ref().or(caller_agent_id) {
            let agent_handle = {
                {
                    {
                        let parent_agent_id = parent_agent_id.to_owned();
                        self.state
                            .with(move |state| {
                                let parent_agent_id = &parent_agent_id;

                                state.registry.agent_handle(parent_agent_id)
                            })
                            .await
                    }
                }
            };
            match agent_handle {
                Some(handle) if handle.is_closing() => {
                    return Err(format!(
                        "cannot spawn a child of agent {parent_agent_id}: the agent is closing"
                    ));
                }
                Some(_) => {}
                None => {
                    return Err(format!(
                        "cannot spawn a child of agent {parent_agent_id}: the agent is closing or no longer running"
                    ));
                }
            }
        }
        let workflow = if let Some(caller_agent_id) = caller_agent_id {
            self.workflow_metadata_for_agent(caller_agent_id).await
        } else {
            None
        };
        let inherited_project_source = if payload.project_id.is_none() {
            if workflow.is_some() {
                caller_agent_id.cloned()
            } else {
                payload
                    .parent_agent_id
                    .clone()
                    .or_else(|| caller_agent_id.cloned())
            }
        } else {
            None
        };
        if let Some(source_agent_id) = inherited_project_source
            && let Some(project_id) = self.agent_project_id(&source_agent_id).await
        {
            payload.project_id = Some(project_id);
        }
        notify_workbench_spawn_waiting_test_hook(self);
        let _project_binding = if let Some(project_id) = payload.project_id.as_ref() {
            Some(
                self.project_catalog
                    .reserve_bindings(vec![project_id.clone()])
                    .await?,
            )
        } else {
            None
        };
        let requested_roots = match &payload.params {
            SpawnAgentParams::New {
                workspace_roots, ..
            } => workspace_roots.clone(),
            SpawnAgentParams::Resume { .. } | SpawnAgentParams::Fork { .. } => {
                return Err("agent-control MCP spawn must use kind=new".to_owned());
            }
        };
        let workspace_roots = self
            .resolve_spawn_workspace_roots(payload.project_id.as_ref(), &requested_roots)
            .await?;
        let SpawnAgentParams::New {
            workspace_roots: roots,
            ..
        } = &mut payload.params
        else {
            return Err("agent-control MCP spawn must use kind=new".to_owned());
        };
        *roots = workspace_roots;
        if let Some(workflow) = workflow {
            let backend_kind = match &payload.params {
                SpawnAgentParams::New { backend_kind, .. } => *backend_kind,
                SpawnAgentParams::Resume { .. } | SpawnAgentParams::Fork { .. } => {
                    return Err(
                        "workflow child agents spawned through MCP must use kind=new".to_owned(),
                    );
                }
            };
            self.ensure_workflow_backend_declared(&workflow, backend_kind)
                .await?;
            if let Some(caller_agent_id) = caller_agent_id {
                payload.parent_agent_id = Some(caller_agent_id.clone());
            }
            let agent_id = self
                .spawn_agent_with_origin_config_and_team(
                    payload,
                    SpawnAgentContext {
                        origin: AgentOrigin::Workflow,
                        input_origin: Some(input_origin),
                        workflow: Some(workflow.clone()),
                        ..Default::default()
                    },
                )
                .await
                .map_err(|error| error.to_string())?;
            self.workflow_note_agent(&workflow.workflow_run_id, agent_id.clone(), false)
                .await?;
            return Ok(agent_id);
        }

        self.spawn_agent_with_origin_config_and_team(
            payload,
            SpawnAgentContext {
                origin: AgentOrigin::AgentControl,
                input_origin: Some(input_origin),
                ..Default::default()
            },
        )
        .await
        .map_err(|error| error.to_string())
    }

    pub(crate) async fn resolve_spawn_workspace_roots(
        &self,
        project_id: Option<&ProjectId>,
        requested: &[String],
    ) -> Result<Vec<String>, String> {
        let Some(project_id) = project_id else {
            if requested.is_empty() {
                return Err(
                    "workspace_roots must contain at least one root when project_id is omitted"
                        .to_owned(),
                );
            }
            return Ok(requested.to_vec());
        };
        {
            let requested = requested.to_owned();
            let project_id = project_id.clone();
            self.state.with(move |state| {
let requested = &requested;
let project_id = &project_id;

        if state.project_store.is_removing(project_id) {
            return Err(format!(
                "cannot spawn agent in workbench {project_id} because it is being removed"
            ));
        }
        let project = state
            .project_store
            .list()?
            .into_iter()
            .find(|project| &project.id == project_id)
            .ok_or_else(|| format!("cannot spawn agent in missing project {project_id}"))?;
        if project.is_removing_workbench() {
            return Err(format!(
                "cannot spawn agent in workbench {project_id} because it is being removed"
            ));
        }
        let authoritative = project
            .root_paths()
            .into_iter()
            .map(|root| root.0)
            .collect::<Vec<_>>();
        if requested.is_empty() {
            return Ok(authoritative);
        }
        let requested_set = requested.iter().collect::<HashSet<_>>();
        let authoritative_set = authoritative.iter().collect::<HashSet<_>>();
        if requested_set != authoritative_set {
            return Err(format!(
                "workspace_roots {:?} do not match authoritative roots {:?} for project {}",
                requested, authoritative, project_id
            ));
        }
        Ok(authoritative)

}).await
        }
    }

