    pub(crate) async fn commit_project(
        &self,
        connection_host_stream: &StreamPath,
        project_output_stream: Stream,
        project_id: ProjectId,
        payload: ProjectGitCommitPayload,
    ) -> AppResult<()> {
        const OPERATION: &str = "project_git_commit";
        let root = payload.root;
        let message = payload.message;
        let project_store = {
            {
                self.state
                    .with(move |state| Arc::clone(&state.project_store))
                    .await
            }
        };
        let project = load_project(&project_store, &project_id, OPERATION).await?;
        let commit_hash = commit(&project, &root, &message)
            .map_err(|error| project_command_error(OPERATION, error))?;
        let result_payload = ProjectGitCommitResultPayload {
            root: root.clone(),
            commit_hash,
        };
        let result_payload = serde_json::to_value(&result_payload).map_err(|error| {
            AppError::internal_message(
                OPERATION,
                "failed to serialize project git commit result payload",
                error,
            )
        })?;
        let _ = project_output_stream.send_value(FrameKind::ProjectGitCommitResult, result_payload);
        self.refresh_after_project_mutation(
            connection_host_stream,
            project_output_stream.clone(),
            project_id,
            None,
        )
        .await?;
        Ok(())
    }

    pub(crate) async fn create_review(
        &self,
        connection_host_stream: &StreamPath,
        project_output_stream: &Stream,
        project_id: ProjectId,
        payload: ReviewCreatePayload,
    ) -> AppResult<()> {
        const OPERATION: &str = "review_create";
        tracing::info!(
            project_id = %project_id,
            selection_kind = payload.selection.kind_name(),
            connection_stream = %connection_host_stream,
            output_stream = %project_output_stream.path(),
            "received review_create"
        );
        let (project_store, review_registry) = {
            {
                self.state
                    .with(move |state| {
                        (
                            Arc::clone(&state.project_store),
                            state.review_registry.clone(),
                        )
                    })
                    .await
            }
        };
        let project = load_project(&project_store, &project_id, OPERATION).await?;
        let normalized_selection = review_create_selection(&project, &payload.selection)
            .map_err(|error| AppError::invalid(OPERATION, error))?;
        let selection_root = match &normalized_selection {
            ReviewDiffSelection::Root { root, .. } => Some(root),
            ReviewDiffSelection::CommittedRange { root, .. } => Some(root),
            ReviewDiffSelection::AllUncommitted | ReviewDiffSelection::Workspace { .. } => None,
        };

        let diff_started = Instant::now();
        tracing::debug!(
            project_id = %project_id,
            selection_kind = payload.selection.kind_name(),
            root = selection_root.map(|root| root.0.as_str()).unwrap_or("<workspace>"),
            "reading initial review diffs"
        );
        let diff_selection = normalized_selection.clone();
        let diff_result =
            tokio::task::spawn_blocking(move || read_review_diffs(&project, &diff_selection))
                .await
                .map_err(|error| {
                    AppError::internal_message(OPERATION, "review diff task failed", error)
                })?;
        let diffs = match diff_result {
            Ok(diffs) => {
                let stats = host_diff_stats(&diffs);
                tracing::info!(
                    project_id = %project_id,
                    selection_kind = payload.selection.kind_name(),
                    root = selection_root.map(|root| root.0.as_str()).unwrap_or("<workspace>"),
                    diff_count = stats.diff_count,
                    file_count = stats.file_count,
                    hunk_count = stats.hunk_count,
                    line_count = stats.line_count,
                    elapsed_ms = diff_started.elapsed().as_millis() as u64,
                    "read initial review diffs"
                );
                diffs
            }
            Err(error) => {
                tracing::warn!(
                    project_id = %project_id,
                    selection_kind = payload.selection.kind_name(),
                    root = selection_root.map(|root| root.0.as_str()).unwrap_or("<workspace>"),
                    elapsed_ms = diff_started.elapsed().as_millis() as u64,
                    error_len = error.len(),
                    "failed to read initial review diffs"
                );
                return Err(AppError::internal_message(
                    OPERATION,
                    error.clone(),
                    anyhow!(error),
                ));
            }
        };
        let review_id = ReviewId(Uuid::new_v4().to_string());
        tracing::debug!(
            project_id = %project_id,
            review_id = %review_id,
            root = selection_root.map(|root| root.0.as_str()).unwrap_or("<workspace>"),
            "creating or getting review actor"
        );
        let request = build_create_request(
            review_id.clone(),
            project_id.clone(),
            ReviewCreatePayload {
                request_id: None,
                selection: normalized_selection,
            },
            diffs,
        );
        let review_id = review_registry.create(request).await.map_err(|error| {
            AppError::internal_message(OPERATION, error.clone(), anyhow!(error))
        })?;
        let review_stream = project_output_stream.with_path(review_stream_path(&review_id));
        review_registry
            .subscribe(
                review_id.clone(),
                connection_host_stream.clone(),
                review_stream,
                true,
            )
            .await
            .map_err(|error| {
                AppError::internal_message(OPERATION, error.clone(), anyhow!(error))
            })?;
        tracing::info!(review_id = %review_id, project_id = %project_id, "created or attached review");
        Ok(())
    }

    pub(crate) async fn review_action(
        &self,
        connection_host_stream: &StreamPath,
        review_output_stream: Stream,
        review_id: ReviewId,
        payload: ReviewActionPayload,
    ) -> AppResult<()> {
        const OPERATION: &str = "review_action";
        tracing::info!(
            review_id = %review_id,
            action_kind = payload.kind_name(),
            connection_stream = %connection_host_stream,
            output_stream = %review_output_stream.path(),
            "received review_action"
        );
        let review_registry = {
            {
                self.state
                    .with(move |state| state.review_registry.clone())
                    .await
            }
        };
        if matches!(
            &payload,
            ReviewActionPayload::Preview { .. } | ReviewActionPayload::StartAiReview { .. }
        ) {
            let preview = async {
                let review = review_registry
                    .handle(review_id.clone())
                    .await?
                    .snapshot()
                    .await?;
                let (author, mode, expected) = match &payload {
                    ReviewActionPayload::Preview {
                        author_agent_id,
                        mode,
                    } => (author_agent_id.clone(), Some(*mode), None),
                    ReviewActionPayload::StartAiReview {
                        author_agent_id,
                        mode,
                        expected_plan,
                        ..
                    } => (author_agent_id.clone(), *mode, expected_plan.as_deref()),
                    _ => return Err("Invalid review configuration action".to_owned()),
                };
                let plan = self.review_plan(&review.project_id, author, mode).await?;
                if matches!(&payload, ReviewActionPayload::Preview { .. }) {
                    return Ok(Some(protocol::ReviewEventPayload::Plan { plan }));
                }
                if expected.is_some_and(|expected| expected != &plan) {
                    let updated = serde_json::to_value(protocol::ReviewEventPayload::Plan { plan })
                        .map_err(|error| error.to_string())?;
                    review_output_stream
                        .send_value(FrameKind::ReviewEvent, updated)
                        .map_err(|_| {
                            "Review output closed before the updated preview".to_owned()
                        })?;
                    return Err(
                        "Review configuration changed. Check the updated preview before starting."
                            .to_owned(),
                    );
                }
                if let Some(reason) = &plan.unavailable_reason {
                    return Err(reason.clone());
                }
                if plan.mode == protocol::ReviewMode::Inline {
                    let author = plan
                        .author_agent_id
                        .clone()
                        .ok_or("Choose the authoring agent")?;
                    let scope = match &payload {
                        ReviewActionPayload::StartAiReview { scope, .. } => scope,
                        _ => return Err("Inline scope is missing".to_owned()),
                    };
                    let message = Self::inline_review_guidance(&plan, scope)?;
                    let handle = self
                        .agent_handle(&author)
                        .await
                        .ok_or("The authoring agent is no longer open")?;
                    if !handle
                        .send_input(protocol::AgentInput::SendMessage(
                            protocol::SendMessagePayload {
                                message,
                                images: None,
                                origin: Some(protocol::MessageOrigin::Review {
                                    review_id: review_id.clone(),
                                }),
                                tool_response: None,
                            },
                        ))
                        .await
                    {
                        return Err(
                            "The authoring agent stopped before receiving Inline guidance"
                                .to_owned(),
                        );
                    }
                    return Ok(Some(protocol::ReviewEventPayload::InlineGuidance {
                        author_agent_id: author,
                    }));
                }
                Ok(None)
            }
            .await;
            let event = match preview {
                Ok(None) => None,
                Ok(Some(event)) => Some(event),
                Err(message) => Some(protocol::ReviewEventPayload::Error {
                    error: protocol::ReviewErrorPayload {
                        code: protocol::ReviewErrorCode::ReviewerBackendUnsupported,
                        message,
                        fatal: false,
                        context: protocol::ReviewErrorContext::StartAiReview,
                    },
                }),
            };
            if let Some(event) = event {
                let value = serde_json::to_value(event)
                    .map_err(|error| AppError::internal(OPERATION, anyhow!(error)))?;
                review_output_stream
                    .send_value(FrameKind::ReviewEvent, value)
                    .map_err(|_| AppError::internal(OPERATION, anyhow!("review output closed")))?;
                return Ok(());
            }
        }
        let interrupted_reviewers = if matches!(
            payload,
            ReviewActionPayload::StopAiReview
                | ReviewActionPayload::ClearComments
                | ReviewActionPayload::Cancel
        ) {
            let review = review_registry
                .handle(review_id.clone())
                .await
                .map_err(|error| {
                    AppError::internal_message(OPERATION, error.clone(), anyhow!(error))
                })?
                .snapshot()
                .await
                .map_err(|error| {
                    AppError::internal_message(OPERATION, error.clone(), anyhow!(error))
                })?;
            review
                .ai_reviewer
                .rounds
                .last()
                .into_iter()
                .flat_map(|execution| &execution.reviewers)
                .filter(|reviewer| reviewer.status == protocol::ReviewAiReviewerStatus::Running)
                .filter_map(|reviewer| reviewer.agent_id.clone())
                .collect::<Vec<_>>()
        } else {
            Vec::new()
        };
        // Commit explicit user intent before interrupt-generated idle events can finish the execution.
        review_registry
            .action(review_id, payload, connection_host_stream.clone())
            .await
            .map_err(|error| {
                AppError::internal_message(OPERATION, error.clone(), anyhow!(error))
            })?;
        for agent_id in interrupted_reviewers {
            self.interrupt_agent(&agent_id).await;
        }
        Ok(())
    }

