impl HostHandle {
    /// Record a passive backend capacity update. The host is the sole owner of
    /// this account-wide state; agent connections never retain capacity state.
    /// Collects one backend's capacity now, on user request.
    ///
    /// Refuses backends with no out-of-band source rather than starting a
    /// process that cannot answer, and coalesces into any poll already running.
    pub(crate) async fn refresh_backend_capacity(
        &self,
        backend_kind: BackendKind,
    ) -> AppResult<()> {
        if !crate::backend::supports_out_of_band_capacity(backend_kind) {
            return Err(AppError::invalid(
                "backend_capacity_refresh",
                format!("{backend_kind:?} cannot report capacity without a running agent"),
            ));
        }
        let host = self.clone();
        tokio::spawn(async move {
            crate::capacity_poll::poll_once(
                &host,
                backend_kind,
                crate::capacity_poll::CapacityPollTrigger::Manual,
            )
            .await;
        });
        Ok(())
    }

    pub(crate) async fn installed_backend_kinds(&self) -> Vec<BackendKind> {
        {
            self.state
                .with(move |state| {
                    state
                        .backend_setup
                        .backends
                        .iter()
                        .filter(|info| info.status == protocol::BackendSetupStatus::Installed)
                        .map(|info| info.backend_kind)
                        .collect()
                })
                .await
        }
    }

    /// Claims the poll slot for `backend_kind`, or reports it already taken.
    pub(crate) async fn begin_capacity_poll(&self, backend_kind: BackendKind) -> bool {
        {
            self.state
                .with(move |state| state.capacity_polls_in_flight.insert(backend_kind))
                .await
        }
    }

    pub(crate) async fn end_capacity_poll(&self, backend_kind: BackendKind) {
        self.state
            .with(move |state| state.capacity_polls_in_flight.remove(&backend_kind))
            .await;
    }

    /// What the poller needs to reach a provider, or `None` on a host that is
    /// configured not to run real backend processes.
    pub(crate) async fn capacity_probe_context(
        &self,
        backend_kind: BackendKind,
    ) -> Option<crate::backend::BackendProbeContext> {
        {
            self.state
                .with(move |state| {
                    if state.skip_real_backend_probe {
                        return None;
                    }
                    // The same root the session-schema probe uses. An empty list makes the
                    // ACP adapter resolve no working directory, which the Kiro usage
                    // command then fails in — the probe needs somewhere to run, not a
                    // meaningful workspace.
                    let workspace_roots =
                        backend_probe_workspace_root(state.backend_probe_workspace_root.as_deref())
                            .map(|root| vec![root])
                            .unwrap_or_default();
                    Some(crate::backend::BackendProbeContext {
                        workspace_roots,
                        program: state.backend_probe_programs.get(&backend_kind).cloned(),
                        ..Default::default()
                    })
                })
                .await
        }
    }

    pub(crate) async fn record_backend_capacity(
        &self,
        backend_kind: BackendKind,
        state: BackendCapacityState,
    ) {
        self.record_backend_capacity_with_emit(backend_kind, state, false)
            .await;
    }

    /// Records a reading, optionally forcing a broadcast even when the state is
    /// unchanged.
    ///
    /// Identical repeats are normally swallowed: a passive report arriving again
    /// with the same numbers is an observation, not a state change, and fanning
    /// it out is pure churn. A **user-requested refresh is different** — if the
    /// quota genuinely has not moved, suppressing the frame leaves the age
    /// frozen and the click indistinguishable from a broken button. So the
    /// manual path forces the emit and the UI can show it was just re-read.
    pub(crate) async fn record_backend_capacity_with_emit(
        &self,
        backend_kind: BackendKind,
        state: BackendCapacityState,
        force_emit: bool,
    ) {
        let (repeated, retrieved_at_ms) = {
            {
                self.state
                    .with(move |host_state| {
                        let now_ms = capacity_now_ms();
                        tracing::debug!(
                            ?backend_kind,
                            ?state,
                            force_emit,
                            received_at_ms = now_ms,
                            "received backend capacity reading"
                        );
                        let (state, retrieved_at_ms, freshness) = resolve_recorded_capacity(
                            host_state.backend_capacity.get(&backend_kind),
                            state,
                            now_ms,
                        );
                        let snapshot = BackendCapacitySnapshot {
                            backend_kind,
                            state,
                            retrieved_at_ms,
                            freshness,
                            refreshable: crate::backend::supports_out_of_band_capacity(
                                backend_kind,
                            ),
                        };
                        let repeated = if host_state
                            .backend_capacity
                            .get(&backend_kind)
                            .is_some_and(|current| current.state == snapshot.state)
                        {
                            let current = host_state
                                .backend_capacity
                                .get_mut(&backend_kind)
                                .expect("checked capacity snapshot must exist");
                            current.retrieved_at_ms = retrieved_at_ms;
                            current.freshness = snapshot.freshness;
                            let snapshots = backend_capacity_snapshots(host_state);
                            host_state
                                .usage_limits_tx
                                .send_modify(|signal| signal.snapshots = snapshots);
                            if force_emit {
                                fan_out_backend_capacity(host_state);
                            }
                            true
                        } else {
                            host_state.backend_capacity.insert(backend_kind, snapshot);
                            fan_out_backend_capacity(host_state);
                            false
                        };
                        (repeated, retrieved_at_ms)
                    })
                    .await
            }
        };
        let host = self.clone();
        tokio::spawn(async move {
            tokio::time::sleep(Duration::from_secs(60 * 60)).await;
            host.mark_backend_capacity_stale(backend_kind, retrieved_at_ms)
                .await;
        });
        if repeated {
            tracing::debug!(?backend_kind, "refreshed identical passive capacity report");
        }
    }

    async fn mark_backend_capacity_stale(&self, backend_kind: BackendKind, retrieved_at_ms: u64) {
        {
            self.state
                .with(move |state| {
                    let now = capacity_now_ms();
                    let Some(snapshot) = state.backend_capacity.get_mut(&backend_kind) else {
                        return;
                    };
                    if snapshot.retrieved_at_ms != retrieved_at_ms {
                        return;
                    }
                    let BackendCapacityState::Known { report } = &snapshot.state else {
                        return;
                    };
                    snapshot.state = BackendCapacityState::Stale {
                        report: report.clone(),
                        stale_since_ms: now,
                        // Aged out on its own; nothing failed.
                        last_error: None,
                    };
                    snapshot.freshness = protocol::CapacityFreshness::Stale {
                        age_ms: now.saturating_sub(retrieved_at_ms),
                        threshold_ms: CAPACITY_FRESHNESS_THRESHOLD_MS,
                    };
                    fan_out_backend_capacity(state);
                })
                .await
        }
    }
    async fn refresh_after_project_mutation(
        &self,
        connection_host_stream: &StreamPath,
        project_output_stream: Stream,
        project_id: ProjectId,
        _path: Option<ProjectPath>,
    ) -> AppResult<()> {
        let handle = self
            .ensure_host_project_subscription(
                connection_host_stream,
                &project_output_stream,
                project_id,
                "project_mutation_refresh",
            )
            .await?;
        handle
            .refresh()
            .await
            .map_err(|error| project_command_error("project_mutation_refresh", error))?;
        Ok(())
    }

    async fn terminal_handle(
        &self,
        connection_host_stream: &StreamPath,
        terminal_id: &TerminalId,
    ) -> AppResult<TerminalHandle> {
        {
            let connection_host_stream = connection_host_stream.to_owned();
            let terminal_id = terminal_id.to_owned();
            self.state
                .with(move |state| {
                    let connection_host_stream = &connection_host_stream;
                    let terminal_id = &terminal_id;

                    state
                        .terminal_streams
                        .get(&(connection_host_stream.clone(), terminal_id.clone()))
                        .cloned()
                        .ok_or_else(|| {
                            AppError::not_found(
                                "terminal_lookup",
                                format!(
                                    "terminal {} is not owned by host stream {}",
                                    terminal_id, connection_host_stream
                                ),
                            )
                        })
                })
                .await
        }
    }
}

async fn resolve_terminal_launch(
    project_store: &Arc<ProjectCatalogHandle>,
    payload: TerminalCreatePayload,
) -> AppResult<TerminalLaunchInfo> {
    const OPERATION: &str = "terminal_create";
    match payload.target {
        TerminalLaunchTarget::HostDefault => {
            let cwd = std::env::current_dir()
                .context("failed to resolve host default cwd")
                .map_err(|error| AppError::internal(OPERATION, error))?
                .display()
                .to_string();
            Ok(TerminalLaunchInfo {
                execution_project: None,
                project_id: None,
                root: None,
                cwd,
                cols: payload.cols,
                rows: payload.rows,
                command: TerminalLaunchCommand::DefaultShell,
            })
        }
        TerminalLaunchTarget::Project {
            project_id,
            root,
            relative_cwd,
        } => {
            let project = load_project(project_store, &project_id, OPERATION).await?;
            let roots = project.root_paths().into_iter().collect::<HashSet<_>>();
            if !roots.contains(&root) {
                return Err(AppError::invalid(
                    OPERATION,
                    format!(
                        "cannot create terminal in root {} that is not part of project {}",
                        root, project_id
                    ),
                ));
            }

            let cwd = resolve_project_terminal_cwd(&root, relative_cwd.as_deref())
                .map_err(|error| AppError::invalid(OPERATION, error))?;
            Ok(TerminalLaunchInfo {
                execution_project: Some(project),
                project_id: Some(project_id),
                root: Some(root),
                cwd,
                cols: payload.cols,
                rows: payload.rows,
                command: TerminalLaunchCommand::DefaultShell,
            })
        }
        TerminalLaunchTarget::Path { cwd } => {
            let trimmed = cwd.trim();
            if trimmed.is_empty() {
                return Err(AppError::invalid(
                    OPERATION,
                    "terminal path cwd must not be empty",
                ));
            }
            if !Path::new(trimmed).is_absolute() {
                return Err(AppError::invalid(
                    OPERATION,
                    format!("terminal path cwd must be absolute: {}", trimmed),
                ));
            }
            Ok(TerminalLaunchInfo {
                execution_project: None,
                project_id: None,
                root: None,
                cwd: trimmed.to_owned(),
                cols: payload.cols,
                rows: payload.rows,
                command: TerminalLaunchCommand::DefaultShell,
            })
        }
    }
}

fn resolve_project_terminal_cwd(
    root: &ProjectRootPath,
    relative_cwd: Option<&str>,
) -> Result<String, String> {
    let Some(relative_cwd) = relative_cwd else {
        return Ok(root.0.clone());
    };
    validate_terminal_relative_path(relative_cwd)?;
    Ok(Path::new(&root.0)
        .join(relative_cwd)
        .to_string_lossy()
        .to_string())
}

fn validate_terminal_relative_path(path: &str) -> Result<(), String> {
    if path.trim().is_empty() {
        return Err("terminal relative_cwd must not be empty".to_owned());
    }

    let relative = Path::new(path);
    if !relative.is_relative() {
        return Err(format!("terminal relative_cwd must be relative: {}", path));
    }

    for component in relative.components() {
        match component {
            Component::Normal(_) | Component::CurDir => {}
            Component::ParentDir => {
                return Err(format!(
                    "terminal relative_cwd must not contain '..': {}",
                    path
                ));
            }
            Component::RootDir | Component::Prefix(_) => {
                return Err(format!("terminal relative_cwd must be relative: {}", path));
            }
        }
    }

    Ok(())
}

impl HostHandle {
    pub(crate) async fn accept_learning_input(
        &self,
        agent_id: &AgentId,
        id: protocol::HumanInputId,
        source: protocol::HumanInputSource,
        message: String,
    ) -> Result<bool, String> {
        let handle = self
            .agent_handle(agent_id)
            .await
            .ok_or("Human input target is unavailable")?;
        let snapshot = handle.snapshot();
        let assistant_context = match handle.read_latest_output().await {
            Some(Ok(protocol::AgentControlOutput::Message { text })) => {
                text.chars().take(4096).collect()
            }
            Some(Ok(
                protocol::AgentControlOutput::Empty | protocol::AgentControlOutput::Error { .. },
            )) => String::new(),
            _ => {
                let reason = "Cannot read the accepted human input's assistant context; no analysis was scheduled".to_owned();
                self.config.report_input_failure(reason.clone())?;
                return Err(reason);
            }
        };
        self.config
            .human(protocol::AcceptedHumanInput {
                id,
                source,
                agent_id: agent_id.clone(),
                session_id: snapshot.session_id,
                project_id: snapshot.project_id,
                message,
                assistant_context,
            })
            .await
    }
    pub(crate) async fn learning_action(
        &self,
        action: protocol::SelfImprovementAction,
    ) -> AppResult<()> {
        self.config
            .action(action)
            .await
            .map_err(|reason| AppError::conflict("self_improvement_action", reason))
    }
    async fn delete_learning_project_rules(
        &self,
        project: &ProjectId,
    ) -> Result<Vec<protocol::SteeringId>, String> {
        self.config.delete_project(project.clone()).await
    }
    #[cfg(feature = "test-support")]
    pub async fn stop_learning_for_test(&self) {
        let mut closed = self.config.state.clone();
        self.config.stop();
        while closed.changed().await.is_ok() {}
    }
    #[cfg(feature = "test-support")]
    pub fn set_learning_script_for_test(
        &self,
        script: crate::backend::mock::MockScript,
    ) -> Result<(), String> {
        self.config.mock_script(script)
    }
}

fn spawn_learning_projection(
    host: WeakHostHandle,
    mut learning: watch::Receiver<protocol::SelfImprovementState>,
    stopped: CancellationToken,
) {
    let worker = async move {
        let Some(initial_host) = host.upgrade() else {
            return;
        };
        let mut canonical_revision = learning.borrow().canonical_revision;
        let initial = initial_host
            .state
            .with(|state| (state.steering_store.list(), state.settings_store.get()))
            .await;
        let mut previous_steering = match initial.0 {
            Ok(rules) => rules,
            Err(reason) => {
                tracing::error!(reason = %reason, "Cannot initialize steering projection");
                return;
            }
        };
        let mut previous_settings = match initial.1 {
            Ok(settings) => Some(settings),
            Err(reason) => {
                tracing::error!(reason = %reason, "Cannot initialize settings projection");
                return;
            }
        };
        drop(initial_host);
        loop {
            let closed = tokio::select! { _ = stopped.cancelled() => break, changed = learning.changed() => changed.is_err() };
            let mut snapshot = learning.borrow_and_update().clone();
            if closed {
                let reason = "Self-improvement configuration and accounting are unavailable; the current author turn is not interrupted".to_owned();
                snapshot.error = Some(reason.clone());
                for scope in &mut snapshot.scopes {
                    scope.status = protocol::LearningStatus::Failed {
                        reason: reason.clone(),
                    };
                }
            }
            let Some(host) = host.upgrade() else {
                break;
            };
            #[cfg(feature = "test-support")]
            if snapshot.canonical_revision != canonical_revision {
                let gate = {
                    host.state
                        .with(move |state| state.learning_projection_test_gate.take())
                        .await
                };
                if let Some(gate) = gate {
                    wait_for_spawn_operation_test_gate_inner(&gate).await;
                }
            }
            let projected = {
                let previous_steering = previous_steering.clone();
                let previous_settings = previous_settings.clone();

                host.state.with(move |state| {


                let mut previous_steering = previous_steering;
                let mut previous_settings = previous_settings;
                let mut canonical_revision = canonical_revision;

            if snapshot.canonical_revision != canonical_revision {
                match (state.steering_store.list(), state.settings_store.get()) {
                    (Ok(current), Ok(settings)) => {
                        for old in &previous_steering {
                            if !current.iter().any(|rule| rule.id == old.id) {
                                fan_out_steering_notify(
                                    state,
                                    SteeringNotifyPayload::Delete { id: old.id.clone() },
                                );
                            }
                        }
                        for steering in &current {
                            if !previous_steering.contains(steering) {
                                fan_out_steering_notify(
                                    state,
                                    SteeringNotifyPayload::Upsert {
                                        steering: steering.clone(),
                                    },
                                );
                            }
                        }
                        previous_steering = current;
                        if previous_settings.as_ref() != Some(&settings) {
                            fan_out_host_settings(state, settings.clone(), false);
                        }
                        previous_settings = Some(settings);
                        canonical_revision = snapshot.canonical_revision;
                    }
                    (Err(reason), _) | (_, Err(reason)) => {
                        tracing::error!(reason = %reason, "Cannot project canonical learned changes");
                        snapshot.error = Some("A learned change was saved, but its canonical steering or settings could not be read. Restore the canonical store; the next self-improvement event will reproject the unapplied revision. The author turn is not interrupted.".into());
                        snapshot.canonical_revision = canonical_revision;
                    }
                }
            }
            let usage_changed = !snapshot.usage.is_empty();
            match serde_json::to_value(snapshot) {
                Ok(value) => {
                    state.host_streams.retain(|_, subscriber| {
                        emit_or_queue_host_frame(
                            subscriber,
                            FrameKind::SelfImprovementNotify,
                            value.clone(),
                        )
                        .is_ok()
                    });
                }
                Err(_) => tracing::error!("Cannot serialize self-improvement state"),
            }

                (previous_steering, previous_settings, canonical_revision, usage_changed)
            }).await
            };
            previous_steering = projected.0;
            previous_settings = projected.1;
            canonical_revision = projected.2;
            let usage_changed = projected.3;
            if usage_changed {
                host.fan_out_task_token_usages().await;
            }
            if closed {
                break;
            }
        }
    };
    if let Ok(runtime) = tokio::runtime::Handle::try_current() {
        runtime.spawn(worker);
    } else {
        let _ = std::thread::Builder::new()
            .name("tyde-learning-projection".into())
            .spawn(move || {
                match tokio::runtime::Builder::new_current_thread()
                    .enable_all()
                    .build()
                {
                    Ok(runtime) => runtime.block_on(worker),
                    Err(_) => tracing::error!("Cannot start learning projection runtime"),
                }
            });
    }
}

fn attach_learning_usage(
    payloads: &mut [TaskTokenUsagePayload],
    usage: &[protocol::LearningUsage],
) {
    for payload in payloads {
        payload.helper_usage = usage
            .iter()
            .filter(|usage| {
                usage
                    .origin_agent_ids
                    .iter()
                    .any(|id| payload.breakdown.iter().any(|entry| &entry.agent_id == id))
                    || usage.origin_session_ids.iter().any(|id| {
                        payload
                            .breakdown
                            .iter()
                            .any(|entry| entry.session_id.as_ref() == Some(id))
                    })
            })
            .cloned()
            .collect();
        payload.total = aggregate_task_token_usage(
            payload
                .breakdown
                .iter()
                .map(|entry| &entry.usage)
                .chain(payload.helper_usage.iter().map(|usage| &usage.usage)),
        );
        payload.backends = task_backend_rollups(&payload.breakdown, &payload.helper_usage);
    }
}

fn attach_learning_accounting(
    payloads: &mut [TaskTokenUsagePayload],
    result: Result<Vec<protocol::LearningUsage>, String>,
) {
    match result {
        Ok(usage) => attach_learning_usage(payloads, &usage),
        Err(reason) => {
            tracing::error!(reason = %reason, "Analyzer accounting unavailable; publishing explicitly incomplete totals");
            for payload in payloads {
                let unknown = TaskTokenUsageScope::Unavailable {
                    reason: TaskTokenUsageUnavailableReason::HelperAccountingUnavailable,
                };
                payload.total = aggregate_task_token_usage(
                    payload
                        .breakdown
                        .iter()
                        .map(|entry| &entry.usage)
                        .chain(std::iter::once(&unknown)),
                );
            }
        }
    }
}
